                'इतरांच्या शारीरिक गरजांबाबत आदर ठेवतो, परंतु त्याबाबतची कृती मर्यादित असते. आरोग्यविषयक समस्यांबाबत थोडीफार चिंता व्यक्त करतो.',
                'सहकाऱ्यांना मदत करण्याचा प्रयत्न करतो पण सातत्य ठेवत नाही.',
                'खेळताना इतरांची काळजी घेण्याचा प्रयत्न करतो, सुरक्षितता नियम समजून घेतो.',
                'आजारी सहकाऱ्याबद्दल सहानुभूती व्यक्त करतो.',
            ],
            'parvat' => [
                'अपंग विद्यार्थ्यांसाठी मदतीचा हात पुढे करतो, त्यांना खेळात, उपक्रमात सामावून घेतो. शाळा परिसरात शारीरिक स्वच्छतेविषयी सतर्कता बाळगतो.',
                'सहकाऱ्यांच्या शारीरिक गरजा समजून त्यांना सहकार्य करतो. शाळेत स्वच्छता राखण्यासाठी पुढाकार घेतो.',
                'दुखापत झालेल्या मित्रांना प्रथमोपचाराबद्दल माहिती देतो आणि शिक्षकांना कळवतो.',
                'शारीरिकदृष्ट्या कमकुवत सहकाऱ्यांना खेळात सामावून घेण्यासाठी स्वतः पुढाकार घेतो.',
            ],
            'akash' => [
                'शाळा व समाज पातळीवर आरोग्य जनजागृती उपक्रमांचे नियोजन व अंमलबजावणी करतो. इतर विद्यार्थ्यांच्या शारीरिक व मानसिक गरजा समजून घेतो.',
                'सर्व सहकाऱ्यांच्या शारीरिक गरजांबद्दल अत्यंत संवेदनशील आहे. आरोग्य मोहिमांमध्ये सक्रिय सहभाग घेतो.',
                'शाळेतील आरोग्य व स्वच्छता उपक्रमांचे नेतृत्व करतो. इतरांना प्रेरणा देतो.',
                'विशेष गरजा असलेल्या विद्यार्थ्यांसाठी सहाय्यक वातावरण निर्माण करण्यात सक्रिय भूमिका बजावतो.',
            ],
        ],
        'creativity' => [
            'pailu' => [
                'शारीरिक हालचालींमध्ये नवीन प्रयत्न करण्यास उत्सुक असतो परंतु आत्मविश्वास कमी असतो.',
                'खेळात नवीन पद्धती वापरण्यास अजून सुरुवात करत आहे.',
                'शिक्षकाच्या मार्गदर्शनाखाली साध्या शारीरिक कृती करतो.',
                'शारीरिक उपक्रमांमध्ये सहभाग घेतो पण स्वतःच्या कल्पना अजून व्यक्त करत नाही.',
            ],
            'pravah' => [
                'त्याच्या हालचालींमध्ये कल्पकतेचे प्राथमिक दर्शन होते. शारीरिक कृतीतून वेगवेगळ्या आकारांची निर्मिती करण्याचा प्रयत्न केला.',
                'खेळात स्वतःच्या नवीन नियम सुचवतो. शारीरिक हालचालींमध्ये थोडे वेगळेपण दाखवतो.',
                'व्यायामाचे नवीन प्रकार शिकण्यास उत्सुक असतो आणि प्रयत्न करतो.',
                'शारीरिक कृतींमध्ये कधीकधी नवीन कल्पना सुचवतो, पण अंमलबजावणीसाठी मदत लागते.',
            ],
            'parvat' => [
                'खेळात स्वतःची शैली दाखवत सहभाग घेतला. वस्तूंचा वापर करून नवीन हालचालींचे सादरीकरण केले (उदा. दोरी, बॉल, आकृत्या).',
                'शारीरिक कृतींमध्ये स्वतःच्या सर्जनशील कल्पना राबवतो. नवीन खेळ तयार करतो.',
                'व्यायाम आणि खेळात नाविन्यपूर्ण पद्धती वापरतो. इतरांनाही नवीन हालचाली शिकवतो.',
                'शारीरिक सादरीकरणात (नृत्य, योगासने) स्वतःची शैली विकसित करतो.',
            ],
            'akash' => [
                'इतर विद्यार्थ्यांनाही स्वतःच्या कल्पना वापरण्यास प्रेरणा दिली. शाळेतील उपक्रमात, सादरीकरणात आणि गटक्रियेत सर्जनशील हालचालींचे नेतृत्व केले.',
                'शारीरिक कृतींमध्ये उत्कृष्ट सर्जनशीलता दाखवतो. नवीन खेळ, व्यायाम प्रकार तयार करून इतरांना शिकवतो.',
                'शाळेतील क्रीडा व सांस्कृतिक कार्यक्रमात अभिनव सादरीकरण करतो आणि गटाचे नेतृत्व करतो.',
                'शारीरिक कला (नृत्य, योग, जिम्नॅस्टिक्स) मध्ये मूळ कल्पनांचा वापर करून उत्कृष्ट प्रदर्शन करतो.',
            ],
        ],
    ],
    2 => [ // सामाजिक-भावनिक आणि नैतिक विकास
        'awareness' => [
            'pailu' => [
                'विद्यार्थी आपल्या आजूबाजूच्या सामाजिक व नैतिक गोष्टींची प्राथमिक जाणीव दाखवतो.',
                'वर्गातील मूलभूत नियमांची माहिती आहे पण पालन करताना सातत्य नाही.',
                'चांगले-वाईट वर्तन यातील फरक ओळखण्याचा प्रयत्न करतो.',
                'सामाजिक परिस्थितींमध्ये योग्य वर्तनाबद्दल अजून शिकत आहे.',
            ],
            'pravah' => [
                'विद्यार्थी आपल्या आजूबाजूच्या सामाजिक व नैतिक गोष्टींची जाणीव दाखवतो. वर्गातील नियमांचे पालन करतो.',
                'इतरांशी सभ्यतेने वागतो. "कृपया", "धन्यवाद" यांसारखे शब्द वापरतो.',
                'सत्य बोलण्याचे महत्त्व समजतो आणि बहुतेक वेळा प्रामाणिकपणे वागतो.',
                'गटात काम करताना सहकार्य करतो पण नेतृत्व अजून विकसित होत आहे.',
            ],
            'parvat' => [
                'विद्यार्थी सामाजिक व नैतिक मूल्यांची जाणीव दाखवतो. वर्गातील नियमांचे पालन करतो, स्वतःहून शिस्त पाळतो आणि इतरांना मदत करण्याचा प्रयत्न करतो.',
                'सामाजिक नियम स्वतःहून पाळतो आणि इतरांनाही त्याबद्दल सांगतो. प्रामाणिकपणा, आदर यांचे आचरण करतो.',
                'गटात काम करताना सहकार्य, विश्वास आणि जबाबदारी दाखवतो.',
                'समाजातील विविधतेचा आदर करतो आणि सर्वांशी समानतेने वागतो.',
            ],
            'akash' => [
                'विद्यार्थी सामाजिक व नैतिक मूल्यांची सखोल समज आणि आचरण दोन्ही दाखवतो. इतर विद्यार्थ्यांनाही चांगले वर्तन करायला प्रेरणा देतो.',
                'नैतिक मूल्यांचा आदर्श ठेवतो. सामाजिक जबाबदारी स्वतःहून स्वीकारतो आणि इतरांना मार्गदर्शन करतो.',
                'अन्यायाविरुद्ध आवाज उठवतो, कमकुवत विद्यार्थ्यांचे संरक्षण करतो.',
                'सर्वसमावेशक वातावरण निर्माण करण्यात सक्रिय भूमिका बजावतो. सामुदायिक सेवेत सहभाग घेतो.',
            ],
        ],
        'sensitivity' => [
            'pailu' => [
                'विद्यार्थी इतरांच्या भावना ओळखण्याचा प्रयत्न करतो, पण त्यावर योग्य प्रतिसाद देणे अद्याप शिकत आहे.',
                'मित्रांच्या रडण्याला किंवा आनंदाला प्रतिसाद देतो पण भावना समजून घेण्यात अडचण येते.',
                'स्वतःच्या भावना व्यक्त करताना अडचण येते.',
                'इतरांच्या दुःखाबद्दल जाणीव आहे पण सांत्वन करण्याचे कौशल्य विकसित होत आहे.',
            ],
            'pravah' => [
                'विद्यार्थी इतरांच्या भावना ओळखतो, पण त्यावर योग्य प्रतिसाद देण्यासाठी अजून मार्गदर्शनाची गरज आहे.',
                'मित्रांच्या भावना समजून घेण्याचा प्रयत्न करतो. दुःखी मित्राची विचारपूस करतो.',
                'स्वतःच्या भावना शब्दांतून व्यक्त करू शकतो.',
                'इतरांच्या आनंदात सहभागी होतो पण संघर्षाच्या परिस्थितीत अजून मार्गदर्शन लागते.',
            ],
            'parvat' => [
                'विद्यार्थी इतरांच्या भावना समजून घेतो आणि त्यानुसार योग्य प्रतिसाद देतो. वर्गमित्रांना मदत करतो, त्यांच्या अडचणी जाणतो.',
                'भावनिकदृष्ट्या परिपक्व वर्तन दाखवतो. संघर्षाच्या परिस्थितीत शांतपणे सोडवणूक करतो.',
                'सहकाऱ्यांच्या भावना लक्षात घेऊन त्यांना आधार देतो.',
                'गटात काम करताना सर्वांच्या भावनांची काळजी घेतो आणि सकारात्मक वातावरण राखतो.',
            ],
            'akash' => [
                'विद्यार्थी अत्यंत संवेदनशीलपणे इतरांच्या भावना समजतो आणि सहृदयता दाखवतो. स्वतःहून इतरांच्या भावना लक्षात घेऊन सकारात्मक कृती करतो.',
                'सर्व सहकाऱ्यांबद्दल समान प्रेम आणि आदर दाखवतो. भावनिक आधार देण्यात अत्यंत कुशल आहे.',
                'वर्गातील भावनिक वातावरण सकारात्मक ठेवण्यासाठी सक्रिय प्रयत्न करतो.',
                'इतरांच्या कठीण परिस्थितीत स्वतःहून पुढे येतो आणि मदत करतो.',
            ],
        ],
        'creativity' => [
            'pailu' => [
                'विद्यार्थी साध्या परिस्थितींमध्ये सर्जनशील विचार करण्याचा प्रयत्न करतो.',
                'सामाजिक खेळांमध्ये साध्या भूमिका निभावतो.',
                'गटात काम करताना कल्पना व्यक्त करण्यास संकोच वाटतो.',
                'नाटक, भूमिकाभिनय यात शिक्षकाच्या मदतीने सहभाग घेतो.',
            ],
            'pravah' => [
                'विद्यार्थी साध्या परिस्थितींमध्ये सर्जनशील विचार करतो. त्याच्या कल्पनांमध्ये वेगळेपण असते.',
                'गटात काम करताना काही कल्पना सुचवतो. सामाजिक नाटकांमध्ये उत्साहाने भूमिका निभावतो.',
                'समस्या सोडवताना साध्या पर्यायी उपाय सुचवतो.',
                'सामाजिक उपक्रमांमध्ये सहभाग घेतो आणि थोडे वेगळेपण दाखवतो.',
            ],
            'parvat' => [
                'विद्यार्थी विविध सामाजिक व नैतिक संकल्पनांवर आधारित कल्पक विचार व्यक्त करतो. संवाद, भूमिका आणि कृतींतून आपली सर्जनशीलता स्पष्ट करतो.',
                'सामाजिक समस्यांवर कल्पक उपाय सुचवतो. गटकार्यात नेतृत्वगुण दाखवतो.',
                'नाटक, भूमिकाभिनय यात उत्कृष्ट सर्जनशीलता दाखवतो.',
                'सामुदायिक उपक्रमांचे नवीन स्वरूप सुचवतो आणि राबवतो.',
            ],
            'akash' => [
                'विद्यार्थी सामाजिक, भावनिक आणि नैतिक विषयांवर अत्यंत सर्जनशील आणि स्वतंत्र विचार व्यक्त करतो. नवीन आणि अभिनव कल्पना मांडतो.',
                'सामाजिक समस्यांवर अभिनव उपाय योजतो. इतरांना प्रेरित करतो आणि गटाचे नेतृत्व करतो.',
                'सामुदायिक सेवा, सांस्कृतिक कार्यक्रमांमध्ये नाविन्यपूर्ण उपक्रम राबवतो.',
                'संवाद, चर्चा आणि वादविवादात अत्यंत प्रभावी आणि सर्जनशील विचार मांडतो.',
            ],
        ],
    ],
    3 => [ // बौद्धिक विकास - Cognitive
        'awareness' => [
            'pailu' => [
                'विद्यार्थी चित्र पाहून काही वस्तूंची ओळख सांगण्याचा प्रयत्न करतो.',
                'साध्या प्रश्नांची उत्तरे देताना मार्गदर्शनाची आवश्यकता भासते.',
                '1 ते 10 अंक ओळखण्याचा प्रयत्न करतो. वस्तूंचे वर्गीकरण करताना अडचण येते.',
                'आजूबाजूच्या गोष्टींचे निरीक्षण करण्यास सुरुवात करत आहे.',
            ],
            'pravah' => [
                'विद्यार्थी चित्र पाहून वस्तूंची ओळख सांगतो. साधे निरीक्षण करू शकतो.',
                '1 ते 50 अंक ओळखतो, साधी बेरीज करण्याचा प्रयत्न करतो.',
                'रंग, आकार यांनुसार वस्तू वर्गीकृत करू शकतो.',
                '"का?" आणि "कसे?" असे प्रश्न विचारतो. साध्या कारण-परिणाम संबंध समजतो.',
            ],
            'parvat' => [
                'विद्यार्थी आजूबाजूच्या घटकांचे बारकाईने निरीक्षण करतो. विविध वस्तू, आकार, माप यांमधील साम्य व फरक स्पष्टपणे ओळखतो.',
                '1 ते 100 अंक ओळखतो, बेरीज-वजाबाकी करू शकतो. तार्किक विचार करण्याची क्षमता विकसित होत आहे.',
                'कारण-परिणाम संबंध स्पष्ट करतो. साध्या वैज्ञानिक प्रयोगांमध्ये निरीक्षण नोंदवतो.',
                'समस्या सोडवताना तर्कशुद्ध पद्धतीचा वापर करतो.',
            ],
            'akash' => [
                'विद्यार्थी स्वतंत्रपणे निरीक्षण करतो, मिळालेल्या माहितीचा सखोल विचार करतो. तार्किक दृष्टिकोनातून निष्कर्ष काढतो.',
                'गणितीय संकल्पना स्पष्टपणे समजतो आणि दैनंदिन जीवनात वापरतो. जटिल समस्या सोडवण्यास सक्षम आहे.',
                'वैज्ञानिक दृष्टिकोन विकसित झाला आहे. स्वतंत्र प्रयोग करतो आणि निष्कर्ष काढतो.',
                'समस्यांचे विश्लेषण करून अनेक पर्यायी उपाय सुचवतो.',
            ],
        ],
        'sensitivity' => [
            'pailu' => [
                'विद्यार्थ्याला इतरांच्या विचारांविषयी थोडेफार कुतूहल वाटते.',
                'समूहात अभ्यास करताना इतरांचे ऐकण्याचा प्रयत्न करतो.',
                'शिक्षकाच्या सूचनांवर लक्ष देण्याचा प्रयत्न करतो पण लक्ष विचलित होते.',
                'इतरांच्या उत्तरांबद्दल कुतूहल वाटते पण स्वतःचे मत व्यक्त करत नाही.',
            ],
            'pravah' => [
                'विद्यार्थ्याला इतरांच्या विचारांविषयी कुतूहल वाटते. त्यांचे ऐकतो.',
                'गटात काम करताना इतरांच्या कल्पनांचा आदर करतो.',
                'शिक्षकांच्या सूचना समजून घेतो आणि त्यानुसार कृती करतो.',
                'समूहातील चर्चेत सहभाग घेतो आणि इतरांचे मत ऐकतो.',
            ],
            'parvat' => [
                'समूहातील सदस्य म्हणून सहभाग घेताना सहकाऱ्यांच्या भावनांची आणि दृष्टिकोनांची जाणीव ठेवतो.',
                'इतरांच्या अडचणी समजून मदत करतो. गटकार्यात सहकार्याची भूमिका बजावतो.',
                'विविध दृष्टिकोनांचा आदर करतो आणि त्यातून शिकतो.',
                'शिकताना सहकाऱ्यांना मदत करतो आणि एकत्रित शिक्षणात सक्रिय भाग घेतो.',
            ],
            'akash' => [
                'विद्यार्थी शिकताना अत्यंत समजूतदारपणे आणि सहवेदनेने वागतो. इतरांच्या विचारांची, भावनांची जाण ठेवतो.',
                'सहकाऱ्यांना शिकवण्यात आनंद मानतो. कमकुवत विद्यार्थ्यांना विशेष मदत करतो.',
                'गटकार्यात सर्वांना समान संधी मिळेल याची काळजी घेतो.',
                'शैक्षणिक चर्चांमध्ये सर्वांच्या मतांचा आदर करतो आणि सकारात्मक वातावरण राखतो.',
            ],
        ],
        'creativity' => [
            'pailu' => [
                'विद्यार्थी शिकत असताना नवीन कल्पना व्यक्त करण्याचा थोडाफार प्रयत्न करतो.',
                'प्रश्न सोडवताना एकच पद्धत वापरतो. नवीन मार्ग शोधण्यास अजून सुरुवात करत आहे.',
                'शिक्षकाच्या मदतीने साध्या समस्यांवर विचार करतो.',
                'कल्पनाशक्तीचा वापर करण्यास प्रोत्साहनाची गरज भासते.',
            ],
            'pravah' => [
                'विद्यार्थी शिकत असताना नवीन कल्पना व्यक्त करण्याचा प्रयत्न करतो.',
                'समस्या सोडवताना कधीकधी वेगळी पद्धत सुचवतो.',
                'चित्रांच्या आधारे गोष्टी तयार करतो. कल्पनाशक्तीचा थोडा वापर करतो.',
                'साध्या प्रयोगांमध्ये उत्सुकतेने सहभाग घेतो.',
            ],
            'parvat' => [
                'विद्यार्थी अभ्यासक्रमाशी संबंधित कृतींमध्ये सर्जनशील विचार स्पष्टपणे दाखवतो. गणिती समस्येचे सोडवणूक करताना वेगळी पद्धत सुचवतो.',
                'समस्या सोडवताना अनेक पर्यायी मार्ग शोधतो. प्रयोगात नवीन कल्पना राबवतो.',
                'अभ्यासातील संकल्पना दैनंदिन जीवनाशी जोडतो.',
                'वैज्ञानिक प्रयोगांमध्ये स्वतःच्या कल्पना मांडतो आणि चाचणी करतो.',
            ],
            'akash' => [
                'विद्यार्थी अभ्यासक्रमातील संकल्पनांवर उत्कृष्ट सर्जनशीलता दाखवतो. नवकल्पना मांडतो, विविध समस्यांवर स्वतंत्र विचार करतो.',
                'गणित, विज्ञान, भाषा या सर्व विषयांमध्ये अभिनव कल्पना मांडतो. संशोधन वृत्ती विकसित झाली आहे.',
                'जटिल समस्यांवर नवीन आणि अनपेक्षित उपाय शोधतो.',
                'इतरांना प्रेरित करणारे प्रकल्प तयार करतो. शैक्षणिक उपक्रमांमध्ये नेतृत्व करतो.',
            ],
        ],
    ],
    4 => [ // भाषा आणि साक्षरता विकास
        'awareness' => [
            'pailu' => [
                'बालक काही ओळखीच्या शब्दांची ओळख करण्याचा प्रयत्न करतो.',
                'मातृभाषेतील साधे शब्द ऐकून समजतो पण बोलताना अडचण येते.',
                'अक्षर ओळख अजून सुरुवातीच्या टप्प्यावर आहे. चित्रे पाहून नावे सांगण्याचा प्रयत्न करतो.',
                'स्वर-व्यंजने ओळखण्यास शिकत आहे.',
            ],
            'pravah' => [
                'बालक ओळखीच्या शब्दांची ओळख करू शकतो. परिचित चित्रांशी संबंधित शब्द ओळखतो.',
                'मराठी बाराखडी ओळखतो, काही शब्द वाचण्याचा प्रयत्न करतो.',
                'साधे वाक्य बोलतो. प्रश्नांची थोडक्यात उत्तरे देतो.',
                'चित्रपुस्तकातील गोष्टी ऐकतो आणि चित्रे पाहून माहिती सांगतो.',
            ],
            'parvat' => [
                'बालक ओळखीच्या अक्षरांपासून शब्द तयार करतो आणि त्यांचे अर्थ समजून घेतो. चित्रावरून योग्य शब्द किंवा वाक्य तयार करतो.',
                'स्पष्ट वाक्ये बोलतो आणि लिहितो. कविता, गोष्टी सांगू शकतो.',
                'दोन भाषांमध्ये (L1 व L2) साधा संवाद साधू शकतो.',
                'शब्दसंग्रह वाढत आहे. नवीन शब्दांचा अर्थ विचारतो आणि वापरतो.',
            ],
            'akash' => [
                'बालक आत्मविश्वासाने दोन्ही भाषांमध्ये (L1 व L2) संवाद साधतो. गोष्टी, कविता, धडे वाचून त्यातील आशय स्पष्ट समजावतो.',
                'उत्कृष्ट वाचन, लेखन आणि बोलण्याची क्षमता दाखवतो. स्वतःच्या कविता, गोष्टी लिहितो.',
                'भाषेचा सर्जनशील वापर करतो. चर्चा, वादविवाद यात प्रभावी सहभाग घेतो.',
                'दोन्ही भाषांमध्ये अस्खलित संवाद साधतो. इतरांनाही भाषा शिकण्यास मदत करतो.',
            ],
        ],
        'sensitivity' => [
            'pailu' => [
                'बालक परिचित शब्दांवर साधी भावनिक प्रतिक्रिया व्यक्त करतो.',
                'गोष्टी ऐकताना भावना व्यक्त करण्यास अजून शिकत आहे.',
                'इतरांच्या बोलण्यावर साधी प्रतिक्रिया देतो.',
                'भाषेतून भावना व्यक्त करण्याचे कौशल्य विकसित होत आहे.',
            ],
            'pravah' => [
                'बालक परिचित शब्दांवर भावनिक प्रतिक्रिया व्यक्त करतो (आनंद, दुःख, भीती). गोष्टीमधील पात्रांप्रती सहानुभूती दाखवतो.',
                'कथेमधील पात्रांबद्दल आवड-निवड व्यक्त करतो.',
                'इतरांचे बोलणे ऐकतो आणि त्यावर विचार करतो.',
                'कविता ऐकताना भावनिक अनुभव व्यक्त करतो.',
            ],
            'parvat' => [
                'बालक गोष्टीतील पात्रांच्या भावना समजून घेऊन त्यावर मत व्यक्त करतो. संवादात इतरांच्या भावना लक्षात घेऊन विचारपूर्वक शब्द वापरतो.',
                'कथा, कविता यांमधील भावना अचूकपणे ओळखतो आणि चर्चा करतो.',
                'इतरांशी संवाद साधताना त्यांच्या भावनांचा विचार करतो.',
                'साहित्यातील नैतिक संदेश समजून घेतो आणि त्यावर मत व्यक्त करतो.',
            ],
            'akash' => [
                'बालक कथा, कविता किंवा संवादातून मिळणाऱ्या सूक्ष्म भावनाही अचूकपणे ओळखतो आणि स्वतःच्या भावना स्पष्टपणे व्यक्त करतो.',
                'साहित्यातील सूक्ष्म भावना, रस आणि अलंकार समजतो. भावनिक अभिव्यक्ती अत्यंत प्रभावी आहे.',
                'इतरांच्या भाषिक अभिव्यक्तीचा आदर करतो आणि प्रोत्साहन देतो.',
                'कथा, कविता यांमधील गहन अर्थ शोधतो आणि चर्चेत सहभागी होतो.',
            ],
        ],
        'creativity' => [
            'pailu' => [
                'बालक शिक्षकाच्या मदतीने छोट्या गोष्टी ऐकतो आणि सांगण्याचा प्रयत्न करतो.',
                'चित्रे पाहून एक-दोन वाक्ये बोलण्याचा प्रयत्न करतो.',
                'बडबड गीते आणि कविता शिक्षकाबरोबर म्हणण्याचा प्रयत्न करतो.',
                'स्वतःची गोष्ट तयार करण्यास अजून सुरुवात करत आहे.',
            ],
            'pravah' => [
                'बालक चित्राला अनुसरून स्वतःहून छोट्या गोष्टी तयार करण्याचा प्रयत्न करतो.',
                'कविता लक्षात ठेवतो आणि सादर करतो. साध्या गोष्टी सांगू शकतो.',
                'दिलेल्या शब्दांपासून वाक्ये तयार करतो.',
                'चित्रे काढून त्याबद्दल सांगतो. भाषेचा कल्पनाशील वापर करण्याचा प्रयत्न करतो.',
            ],
            'parvat' => [
                'बालक चित्र पाहून स्वतःची गोष्ट रचतो आणि ती शुद्ध व स्पष्ट भाषेत सांगतो. दिलेल्या वाक्यांचे नव्याने फेरबदल करून अर्थपूर्ण वाक्य तयार करतो.',
                'स्वतःच्या कल्पनेने गोष्टी, कविता तयार करतो. भाषेचा सर्जनशील वापर करतो.',
                'कथालेखन, कविता लेखनात कल्पनाशक्तीचा चांगला वापर करतो.',
                'भूमिकाभिनय, संवाद सादरीकरण यात उत्साहाने सहभाग घेतो.',
            ],
            'akash' => [
                'बालक कोणत्याही चित्रावर स्वतःची कल्पनाशक्ती वापरून सुंदर, अर्थपूर्ण आणि रंजक गोष्ट तयार करतो व आत्मविश्वासाने सादर करतो.',
                'मूळ कविता, गोष्टी, नाटक लिहितो. भाषेचा अत्यंत सर्जनशील वापर करतो.',
                'वक्तृत्व, कथाकथन, कविता सादरीकरण यात उत्कृष्ट कामगिरी करतो.',
                'स्वतःचे पुस्तक, कवितासंग्रह तयार करण्याचा प्रयत्न करतो.',
            ],
        ],
    ],
    5 => [ // सौंदर्यात्मक आणि सांस्कृतिक विकास
        'awareness' => [
            'pailu' => [
                'विविध रंग, आकार यांविषयी थोडी उत्सुकता दाखवतो.',
                'कला उपक्रमांकडे थोडेफार लक्ष देतो पण सहभाग कमी आहे.',
                'संगीत ऐकताना प्रतिक्रिया देतो पण ताल-लय ओळखत नाही.',
                'सण-उत्सवांबद्दल माहिती अजून मर्यादित आहे.',
            ],
            'pravah' => [
                'विविध रंग, आकार आणि नमुन्यांविषयी उत्सुकता दाखवतो पण त्यांचा वापर करताना मार्गदर्शनाची गरज भासते.',
                'मूलभूत रंग ओळखतो आणि चित्रे काढण्याचा प्रयत्न करतो.',
                'लोकगीते, भक्तिगीते ऐकतो आणि म्हणण्याचा प्रयत्न करतो.',
                'सण-उत्सवांमध्ये सहभाग घेतो आणि त्यांचे महत्त्व थोडक्यात सांगतो.',
            ],
            'parvat' => [
                'विविध रंग, रेषा, आकार यांचा वापर करून स्वतःची कल्पना स्पष्टपणे व्यक्त करतो.',
                'चित्रकला, हस्तकला यात चांगले कौशल्य दाखवतो. रंगसंगती समजतो.',
                'संगीत आणि नृत्यात ताल-लय ओळखतो आणि सादरीकरण करतो.',
                'सण-उत्सवांचे सांस्कृतिक महत्त्व समजतो आणि सक्रिय सहभाग घेतो.',
            ],
            'akash' => [
                'दृश्य व रंगित कलेतील घटकांचे सूक्ष्म निरीक्षण करून त्यातून नवनवीन कल्पना साकारतो.',
                'कला, संगीत, नृत्य या सर्व क्षेत्रांमध्ये उत्कृष्ट कामगिरी करतो.',
                'सांस्कृतिक कार्यक्रमांचे नियोजन आणि सादरीकरण करतो.',
                'भारतीय संस्कृती आणि परंपरांबद्दल सखोल ज्ञान आणि अभिमान दाखवतो.',
            ],
        ],
        'sensitivity' => [
            'pailu' => [
                'चित्रं, गाणी, नृत्य याकडे थोडेफार लक्ष देतो.',
                'इतरांच्या कलाकृतींबद्दल कमी प्रतिक्रिया देतो.',
                'सांस्कृतिक विविधतेबद्दल अजून जाणीव विकसित होत आहे.',
                'कला उपक्रमांमध्ये इतरांच्या कामाचे निरीक्षण करतो.',
