        'तो सभोवतालच्या घटनांचे सखोल विश्लेषण करतो आणि नवीन संकल्पना आत्मसात करण्यात अग्रेसर आहे.',
        'गोष्टी, आकडे आणि रंग ओळखतो/ओळखते. नवीन गोष्टी जाणून घेण्याची उत्सुकता आहे.',
        'वस्तूंचे वर्गीकरण (रंग, आकार, आकारमान) उत्तम करतो. कारण-परिणाम संबंध समजतो.',
        'गणितीय संकल्पनांची (संख्या ओळख, बेरीज-वजाबाकी, आकार) चांगली समज आहे. दैनंदिन जीवनात गणिताचा वापर करतो.',
        'निरीक्षण करून बारकावे शोधतो. प्रयोग व निरीक्षणाद्वारे शिकतो. "का?" आणि "कसे?" प्रश्न विचारतो.',
        'नमुने (Patterns) ओळखतो व पुढे चालवतो. समस्या सोडवण्यासाठी तार्किक विचार करतो.',
        'क्रम लावणे (लहान ते मोठे, पातळ ते जाड) चांगल्या प्रकारे करतो. लांबी, वजन, वेळ यांची तुलना करतो.',
        'बोधात्मक विकासात अजून प्रगती आवश्यक. एकाग्रता वाढवण्यासाठी अधिक सराव हवा.',
        'वैज्ञानिक दृष्टिकोन विकसित होत आहे - दैनंदिन गोष्टींचे निरीक्षण करतो, तार्किक विचार करतो.',
        'मूलभूत भौमितिक आकार ओळखतो. साधी बेरीज व वजाबाकी करतो. 1 ते 100 पर्यंत संख्या ओळखतो व मोजतो.',
    ],
    4 => [ // भाषा आणि साक्षरता विकास
        'बालक स्वतंत्रपणे कथा लिहू शकतो आणि वाचनातून मिळालेल्या माहितीचा अर्थ खोलवर समजू शकतो. तो भाषिक नियम आणि वाक्यरचनांचा योग्य वापर करत आहे.',
        'अक्षरे, शब्द आणि वाक्य वाचू शकतो/शकते. आपल्या विचारांना बोलून व्यक्त करतो/करते.',
        'दोन भाषांमध्ये (L1 मराठी व L2 इंग्रजी) संवाद साधण्याचा चांगला प्रयत्न करतो. शब्दसंग्रह वाढत आहे.',
        'कथाकथन, कविता, गाणी शिकण्यात रस दाखवतो. बडबड गीते आणि बालकविता उत्साहाने म्हणतो.',
        'मराठी बाराखडी, स्वर-व्यंजने ओळखतो आणि लिहितो. शब्द वाचन आणि लेखनात प्रगती दिसते.',
        'गोष्टी ऐकून त्यातील आशय समजतो. चित्रपुस्तकातील गोष्टी वाचून दाखवतो.',
        'इंग्रजी अक्षरे (A ते Z) ओळखतो व लिहितो. साधे इंग्रजी शब्द वाचण्याचा प्रयत्न करतो.',
        'भाषा कौशल्यात अधिक सराव आवश्यक. वाचन आणि लेखनासाठी घरी पालकांनी मदत करणे गरजेचे.',
        'श्रुतलेखन चांगले करतो. शिक्षकांनी सांगितलेले शब्द/वाक्ये लिहू शकतो.',
