        ],
        'sensitivity_pravah' => [
            'सामाजिक परिस्थितीशी जुळवून घेण्यास त्याला थोडा वेळ लागतो. संवाद साधताना किंवा स्वतःला व्यक्त करताना त्याची खूपच अडचण होते आणि तो मोठ्या समूहात अनेकदा एकटाच राहणे पसंत करतो.',
            'इतरांच्या भावना समजून घेण्यात आणि त्यावर प्रतिक्रिया देण्यात तो थोडा संथ आहे. रागावर नियंत्रण मिळवण्यासाठी आणि समंजसपणे वागण्यासाठी त्याला वारंवार शिक्षकांच्या आणि पालकांच्या वैयक्तिक मदतीची गरज भासते.',
            'खेळताना किंवा गटात काम करताना अनेकदा त्याचे मित्रांसोबत छोटेमोठे वाद होतात. नियम पाळण्याची सवय त्याला अद्याप पूर्णपणे लागलेली नाही, त्यासाठी त्याला सतत प्रेमाने आणि समजून सांगावे लागते.',
            'संकोची स्वभावामुळे तो स्वतःहून नवीन मित्रांशी ओळख करून घेत नाही. बदलत्या परिस्थितीला तोंड देण्याची त्याची तयारी अद्याप पूर्ण नाहीये, त्यामुळे त्याला आत्मविश्वास मिळवून देण्यासाठी जास्त खटाटोप करावी लागते.',
            'वातावरणाशी एकरूप होताना तो अनेकदा भीती किंवा अस्वस्थता दाखवतो. प्राथमिक संवादाची सुरुवात करण्यासाठी तो पूर्णपणे समोरच्या व्यक्तीवर अवलंबून राहतो, स्वतःहून पुढे येऊन बोलण्यास बिचकतो.',
        ],
        'creativity' => [
            'कोणत्याही कामात नवनिर्मिती करण्याची त्याची क्षमता थक्क करणारी आहे. दिलेल्या साधनांचा वापर करून तो अतिशय कल्पक आणि हुबेहूब रचना तयार करतो, ज्यामुळे त्याची कलाकृती नेहमी वर्गात सर्वात वेगळी आणि सुंदर ठरते.',
            'चित्रकला, मातीकाम आणि हस्तकला यात त्याच्याकडे जन्मजातच खूप चांगली कला आहे. रंगसंगतीची निवड, साहित्याची योग्य जुळवाजुळव आणि बारकावे टिपण्याची त्याची पद्धत अत्यंत प्रगल्भ आणि सर्वांसाठी प्रेरणादायी आहे.',
            'स्वतःच्या डोक्याने विचार करून नेहमी काहीतरी नवीन आणि हटके बनवण्याचा त्याचा प्रयत्न वाखाणण्याजोगा आहे. गोष्टी रचणे, नाट्यीकरण करणे किंवा गाणी म्हणण्यात त्याची सर्जनशीलता एकदम उच्च पातळीवर दिसून येते.',
            'कोणतीही साधी वस्तू दिली तरी तिच्यातून तो एक सुरेख मॉडेल किंवा खेळणी तयार करू शकतो. कलेच्या विविध क्षेत्रात तो अत्यंत हुशारीने आणि कल्पकतेने आपला ठसा उमटवतो, त्याचे मन अतिशय सृजनशील आहे.',
            'विचार करण्याची पद्धत चौकटीबाहेरची असून तो प्रत्येक गोष्टीकडे एका नवीन कलात्मक दृष्टिकोनातून बघतो. त्याच्या हाताला अतिशय उत्तम वळण असून तो सुरेख आणि सुबक कलाकुसर करण्यात अतिशय निपुण आहे.',
        ],
        'creativity_parvat' => [
            'दिलेला नमुना बघून तो अत्यंत सुबकपणे आणि हुबेहूब त्याचप्रमाणे कृती पूर्ण करतो. साहित्याचा वापर काळजीपूर्वक करून तो चांगल्या आणि नीटनेटक्या रचना तयार करतो, पण स्वतःहून वेगळी कल्पना लढवत नाही.',
            'रंगकाम आणि हस्तकलेत त्याला बऱ्यापैकी रुची आहे असून तो दिलेले काम वेळेत आणि स्वच्छपणे संपवतो. स्वतःची थोडी कल्पकता त्यात जोडण्याचा त्याचा प्रयत्न निश्चितच चांगला असतो, ज्यात तो यशस्वीही होतो.',
            'साध्या आणि सोप्या कृती तो योग्य प्रकारे पार पडतो. कागदकाम आणि साध्या चित्रकलेत त्याचा हात चांगला बसला आहे. मात्र, अत्यंत क्लिष्ट आणि गुंतागुंतीच्या रचना करताना त्याला थोड्या मार्गदर्शनाची गरज लागते.',
            'शिक्षकांनी दिलेल्या सूचनांनुसार तो कलेच्या तासाला चांगला प्रतिसाद देतो. स्वतःहून अतिशय वेगळे काही बनवण्याची धडपड तो फारशी करत नाही, तरीही त्याचे काम नेहमीच उत्तम दर्जाचे आणि व्यवस्थित असते.',
            'मनापासून आणि आवडीने तो कलेचे काम करतो, पण कल्पना विस्तारासाठी त्याला थोड्या प्रोत्साहनाची गरज आहे. विविध रंग आणि आकारांचा तो चांगला वापर करून कलाकृती निश्चितच छान खुलवून दाखवू शकतो.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा तो प्रयत्न करतो, त्यात सुबकतेचा आणि कल्पकतेचा खूपच अभाव दिसतो. हस्तकलेचे आणि चित्रकलेचे काम पूर्ण करण्यासाठी तो पूर्णपणे मदतीवर अवलंबून राहतो.',
            'रंगकाम करताना रंग बाहेर जातात आणि साहित्याचा वापर करताना त्याला खूप अडचण येते. स्वतःहून कोणतीही नवीन रचना करण्याचा तो अजिबात विचार करत नाही आणि या तासाला अनेकदा कंटाळा करतो.',
            'सूक्ष्म स्नायूंचा विकास अजूनही कमी असल्याने त्याला कागद कापणे, दुमडणे किंवा पेन्सिलने आकार काढणे खूप कठीण जाते. साध्या कृती पूर्ण करण्यासाठी त्याला हाताला धरून वारंवार सराव द्यावा लागतो.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये तो स्वतःला फारसे रमवू शकत नाही. एखादे सोपे चित्र काढायला दिले तरी तो लगेच हार मानतो आणि काम अर्धवट सोडून देण्याची वैतागलेली वृत्ती त्याच्यात दिसून येते.',
            'कोणतीही नवीन कृती किंवा कला निर्माण करण्याची आवड त्याच्यात अजून रुजलेली नाही. त्याच्यातील कलागुणांना वाव देण्यासाठी अगदी प्राथमिक स्तरापासून आणि अत्यंत सोप्या पद्धतीचा वापर करून शिकवावे लागते.',
        ],
    ],
    'H' => [
        'name' => 'उत्तम (High)',
        'awareness' => [
            'विषयाची एकदम सखोल जाण त्याला आहे आणि शिकवलेला भाग तो चटकन आत्मसात करतो. तो स्वतःहून नवीन गोष्टी विचारून समजून घेण्याचा खूप प्रामाणिक प्रयत्न करतो.',
            'वर्गात शिकवलेले घटक लगेच लक्षात ठेवण्याची त्याची हातोटी खूप चांगली आहे. स्वतः शिकलेली माहिती तो इतरांनाही सांगण्यात आणि समजावून देण्यात नेहमीच पुढाकार घेतो.',
            'नव्या संकल्पना व घटकांबद्दल त्याचा समज खूप पक्का आहे, ज्यामुळे तो परीक्षेत चांगले गुण मिळवतो. विचारलेल्या बहुतांश प्रश्नांची अचूक उत्तरे तो पटकन आणि न घाबरता देतो.',
            'अभ्यासात तो खूप हुशार असून परिसरातील नवनवीन गोष्टींचे तो नेहमी बारकाईने निरीक्षण करतो. या निरीक्षणातून तो अनेक चांगले निष्कर्ष स्वतःहून काढतो.',
            'कोणतीही नवीन माहिती मिळवण्याची आणि ती कायमस्वरूपी लक्षात ठेवण्याची त्याची धडपड वाखाणण्याजोगी आहे. सर्वांच्या मते तो एक अत्यंत हुशार आणि अभ्यासू विद्यार्थी आहे.',
        ],
        'awareness_parvat' => [
            'शिक्षकांनी सांगितलेली कामे तो अतिशय प्रामाणिकपणे पूर्ण करतो आणि नियमांचे योग्य पालन करतो. स्वतःहून फार धडपड करत नसला तरी दिलेला अभ्यास वेळेवर करून दाखवतो.',
            'शिकवलेल्या गोष्टी त्याला बहुतांश वेळा समजतात, मात्र त्या ठामपणे सांगण्यासाठी त्याला शिक्षकांच्या आधाराची गरज भासते. उत्तरांमध्ये थोडीफार सुधारणा केल्यास तो खूप चांगली प्रगती करेल.',
            'पायाभूत बाबी समजण्यात त्याला बऱ्यापैकी गती आहे, पण अजूनही वाचन आणि लेखनात त्याला सरावाची गरज आहे. सरावाने तो नक्कीच अधिक चांगल्या प्रकारे स्वतःला व्यक्त करू शकेल.',
            'रोजच्या अभ्यासाव्यतिरिक्त तो इतर अवांतर गोष्टींतही चांगला रस घेतो. प्रश्न विचारल्यास तो शांतपणे आणि बऱ्यापैकी बरोबर उत्तरे देतो, ज्यात अजून प्रगल्भता येणे अपेक्षित आहे.',
            'नवीन घटक शिकण्याची त्याची तयारी असते, परंतु सुरुवातीला तो थोडासा गोंधळून जातो. वारंवार उजळणी दिल्यास तो दिलेला सर्व अभ्यास अत्यंत व्यवस्थित आणि अचूकपणे करू शकतो.',
        ],
        'awareness_pravah' => [
            'प्राथमिक संकल्पना समजून घेण्यास तो अजूनही बराच वेळ घेतो. स्वतःचे विचार स्पष्टपणे आणि ठामपणे मांडण्यासाठी त्याला सतत शिक्षकांनी प्रेमाने मार्गदर्शन करणे खूप आवश्यक आहे.',
            'शिकवलेल्या बाबी लगेच लक्षात राहण्यासाठी त्याला वारंवार शिक्षकांच्या मदतीची आणि वैयक्तिक लक्ष देण्याची नितांत गरज भासते. तो अनेकदा स्वतःहून प्रश्न विचारताना कचरतो.',
            'प्रश्नांची उत्तरे देताना तो खूपदा गडबडतो किंवा चुकीची उत्तरे देतो. त्याला अधिक प्रोत्साहन देऊन आणि गोष्टी सोप्या करून सांगितल्यास तो योग्य दिशेने प्रगती करू शकतो.',
            'नवीन संकल्पना समजून घेण्यासाठी तो धडपड नक्कीच करतो, पण त्याला अनेकदा सहकाऱ्यांच्या मदतीची खूप गरज लागते. त्याचे लक्ष खेळातून अभ्यासाकडे पूर्णपणे वळवण्यासाठी जास्तीचे प्रयत्न हवेत.',
            'विषयाची केवळ वरवरची ओळख झाली असून त्याची अधिक सखोल उजळणी होणे अत्यंत आवश्यक आहे. स्वतःहून पुढाकार घेण्याची सवय त्याला लावण्यासाठी सतत प्रोत्साहन द्यावे लागेल.',
        ],
        'sensitivity' => [
            'मित्रांसोबत वागताना तो नेहमी खूप समझदारपणा आणि सामंजस्याची भूमिका दाखवतो. शाळेत रोज आनंदाने येतो आणि सर्वांशी खूप प्रेमाने आणि आदराने वागतो.',
            'इतरांच्या भावनांचा आणि अडचणींचा तो खूप आदर करतो. वर्गात कोणालाही मदतीची गरज लागली तर तो अत्यंत निस्वार्थीपणे आणि लगेच धावून जातो.',
            'गटात काम करताना स्वतःचे नेतृत्व गुण प्रस्थापित करून सर्वांना बरोबर घेऊन जाण्याची त्याची सवय खूपच छान आणि आदर्शवत आहे.',
            'आजारी किंवा अभ्यासात कमजोर असलेल्या मित्रांची काळजी घेण्यात आणि त्यांना अभ्यासात मदत करण्यात तो नेहमीच पुढे राहतो.',
            'शाळेतील सर्व नियम पाळण्यात आणि शिक्षकांचा आदर करण्यात तो एक उत्तम आणि आदर्श विद्यार्थी आहे. मोठ्या व्यक्तींशी तो अतिशय नम्रपणे आणि आदराने बोलतो.',
        ],
        'sensitivity_parvat' => [
            'सर्वांशी चांगले वागतो आणि शाळेत सहसा कोणाशीही कोणतेही मोठे भांडण करत नाही. नियम आणि शिस्त पाळण्याचा त्याचा प्रयत्न नेहमीच अतिशय चांगला आणि प्रामाणिक असतो.',
            'बहुतांश वेळा तो शांत आणि समजूतदारपणे वागतो आणि शिक्षकांच्या आज्ञेचे व्यवस्थित पालन करतो. परंतु अनोळखी व्यक्तींसमोर तो स्वतःला व्यक्त करताना थोडाफार संकोचतो.',
            'इतरांच्या भावना त्याला समजतात आणि तो मित्रांना सहसा कधीच दुखावत नाही. दैनंदिन व्यवहारात तो दिलेल्या सूचनांचे पालन करून सामाजिक नियमांशी जुळवून घेण्याचा चांगला प्रयत्न करतो.',
            'मित्रांसोबत खेळताना तो सहकार्याची भावना नक्कीच दाखवतो. वागण्यात थोडा शांतपणा आणि लाजाळूपणा आहे, पण गरजेच्या वेळी तो मित्रांना आवर्जून मदत करतो.',
            'वर्गातील शिस्त पाळतो आणि आपल्या कामाशी नेहमी प्रामाणिक राहतो. मोठ्या समूहात बोलण्याची त्याची फारशी हिंमत होत नसली तरी छोट्या गटात तो खूप खेळीमेळीने वावरतो.',
        ],
        'sensitivity_pravah' => [
            'नवीन परिस्थितीत जुळवून घेण्यास आणि लोकांशी मिसळण्यास त्याला खूप जास्त वेळ लागतो. संवाद साधताना किंवा स्वतःला व्यक्त करताना त्याची खूपच मोठी अडचण होते.',
            'इतरांच्या भावना समजून घेण्यात आणि त्यावर योग्य प्रतिक्रिया देण्यात तो अजूनही खूप संथ आहे. त्याला मित्र बनवण्यासाठी आणि समंजसपणे वागण्यासाठी वारंवार मदतीची गरज भासते.',
            'खेळताना किंवा गटात काम करताना अनेकदा त्याचे मित्रांसोबत छोटेमोठे वाद होतात. नियम पाळण्याची सवय त्याला अद्याप पूर्णपणे लागलेली नाही, त्यासाठी सतत समज द्यावी लागते.',
            'लाजाळू स्वभावामुळे तो स्वतःहून नवीन मित्रांशी अजिबात ओळख करून घेत नाही. बदलत्या परिस्थितीला तोंड देण्यासाठी त्याला चांगलाच आत्मविश्वास मिळवून द्यावा लागेल.',
            'वातावरणाशी एकरूप होताना तो अनेकदा भीती, संकोच किंवा अस्वस्थता दाखवतो. तो प्राथमिक संवादाची सुरुवात करण्यासाठी सर्वस्वी समोरच्या व्यक्तीवर किंवा शिक्षकांवर अवलंबून राहतो.',
        ],
        'creativity' => [
            'कोणतेही काम दिले तर तो स्वतःच्या डोक्याने विचार करून त्यातून नवीन काहीतरी सुंदर आणि आकर्षित ठेवणारी गोष्ट नक्कीच बनवून दाखवतो. त्याची ही कला खूप छान आहे.',
            'मातीकाम आणि चित्रकलेत त्याचा हातखंडा खूपच छान आणि सफाईदार आहे. रंगसंगतीची आणि आकारांची अत्यंत उत्तम जाण त्याच्या प्रत्येक रचनेत स्पष्टपणे दिसून येते.',
            'कागदकाम व विविध हस्तकलेतून तो खूप सुंदर आणि कल्पक वस्तू अत्यंत सफाईने बनवतो. त्या वस्तू बघून इतर मुले देखील त्याच्याकडून तसे काम करायला नक्कीच शिकतात.',
            'दिलेल्या साहित्याचा अत्यंत कल्पक वापर करून तो नेहमी काहीतरी हटके आणि नवीन बनवण्याचा प्रामाणिक प्रयत्न करतो, आणि त्यात तो बर्‍याच अंशी यशस्वी देखील ठरतो.',
            'गाणी आणि गोष्टींच्या माध्यमातून स्वतःचे विचार अतिशय नाट्यपूर्णरीत्या मांडण्यात तो वर्गात सगळ्यात भारी आहे. त्याच्यातील नाट्य आणि कलागुण खूपच विलक्षण आहेत.',
        ],
        'creativity_parvat' => [
            'दिलेला नमुना किंवा चित्र बघून तो अत्यंत सुबकपणे आणि हुबेहूब त्याचप्रमाणे कृती पूर्ण करण्याचा चांगला प्रयत्न करतो. त्याचे काम बहुतांश वेळा खूप नीटनेटक्या स्वरूपाचे असते.',
            'रंगकाम आणि हस्तकलेत त्याला बऱ्यापैकी आवड आहे असून तो दिलेले काम वेळेत संपवतो. स्वतःची थोडी बहुत कल्पकता त्यात जोडण्याचा त्याचा प्रयत्न निश्चितच चांगला आणि कौतुकास्पद असतो.',
            'साध्या आणि सोप्या कृती तो खूप योग्य प्रकारे पार पडतो. कागदकाम आणि साध्या चित्रकलेत त्याचा हात चांगला बसला आहे, पण त्याला अजूनही क्लिष्ट कामे करण्यासाठी मदतीची गरज लागते.',
            'शिक्षकांनी दिलेल्या सूचनांनुसार तो कलेच्या तासाला व्यवस्थित प्रतिसाद देतो. स्वतःहून जास्त काही वेगळे बनवण्याची धडपड तो करत नसला, तरी तो सांगितलेले काम उत्तम दर्जाचे करतो.',
            'मनापासून आणि भरपूर आवडीने तो कलेचे काम करतो, पण स्वतःच्या कल्पना विस्तारासाठी त्याला थोड्या अधिक मार्गदर्शनाची आणि प्रोत्साहनाची नक्कीच गरज भासते.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा तो प्रयत्न करतो, त्यात सुबकतेचा आणि बारीकसारीक कलाकुसरीचा खूपच अभाव दिसतो. हस्तकलेच्या कामासाठी तो मदतीवर अवलंबून राहतो.',
            'रंगकाम करताना रंग चित्राच्या नेहमीच बाहेर जातात आणि साहित्याचा वापर करताना त्याला अडचण येते. चित्रकलेच्या तासाला नवीन काही रचना करण्यात तो सहसा रस दाखवत नाही.',
            'सूक्ष्म स्नायूंचा आणि बोटांचा समन्वय अजूनही कमी असल्याने त्याला कागद कापणे किंवा पेन्सिलने अचूक आकार काढणे कठीण जाते. या कृती तो पूर्ण करण्यासाठी स्वतःहून फारसा धडपडत नाही.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये तो स्वतःला फारसे रमवू शकत नाही. एखादे साधे चित्र काढायला दिले तरी तो निरुत्साह दाखवतो आणि काम अपूर्ण सोडण्याची त्याची सवय दिसून येते.',
            'कोणतीही नवीन कृती किंवा कला निर्माण करण्याची आवड त्याच्यात अजून अजिबात रुजलेली नाही. त्याच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व सोप्या पद्धतीने शिकवावे लागते.',
        ],
    ],
    'M' => [
        'name' => 'मध्यम (Medium)',
        'awareness' => [
            'काही महत्त्वाच्या आणि पायाभूत संकल्पना त्याला बऱ्यापैकी समजतात, मात्र त्या ठामपणे सांगताना तो थोडा विचार आणि वेळ घेतो. वारंवार सराव दिल्यास त्याच्या उत्तरात नक्कीच अचूकता येते.',
            'सांगितलेले काम तो पूर्ण करतो पण बऱ्याचदा त्याचे लक्ष थोडे विचलित होते. त्याला वेळेवर काम पूर्ण करण्यासाठी शिक्षकांनी सतत आठवण करून देत राहावे लागते, ज्यामुळे तो काम पूर्ण करतो.',
            'एखादी नवीन गोष्ट किंवा संकल्पना पटकन समजायला त्याला थोडा वेळ लागतो. मात्र, शिक्षकांनी लक्ष देऊन त्याच्याकडून सतत सराव करून घेतल्यास ती गोष्ट तो नक्कीच आत्मसात करतो.',
            'बऱ्याच वेळा तो शांत बसून राहणे पसंत करतो, पण जेव्हा त्याला उत्तर खात्रीशीर माहीत असते, तेव्हा मात्र तो अतिशय उत्साहाने आणि खूप छान उत्तरे देण्याचा प्रयत्न करतो.',
            'आपल्या आजूबाजूच्या घडामोडींची आणि सामान्य गोष्टींची जाण त्याला आहे. परंतु, आपले विचार स्वतःहून स्पष्टपणे आणि योग्य शब्दांत व्यक्त करण्यासाठी तो थोडा संकोच करतो.',
        ],
        'awareness_parvat' => [
            'शिकवलेल्या गोष्टी त्याला बहुतांश वेळा समजतात, मात्र त्या ठामपणे सांगण्यासाठी त्याला शिक्षकांच्या आधाराची गरज भासते. उत्तरांमध्ये थोडीफार सुधारणा केल्यास तो खूप चांगली प्रगती करेल.',
            'पायाभूत बाबी समजण्यात त्याला बऱ्यापैकी गती आहे, पण अजूनही वाचन आणि लेखनात त्याला सरावाची गरज आहे. सरावाने तो नक्कीच अधिक चांगल्या प्रकारे स्वतःला व्यक्त करू शकेल.',
            'रोजच्या अभ्यासाव्यतिरिक्त तो इतर अवांतर गोष्टींतही चांगला रस घेतो. प्रश्न विचारल्यास तो शांतपणे आणि बऱ्यापैकी बरोबर उत्तरे देतो, ज्यात अजून प्रगल्भता येणे अपेक्षित आहे.',
            'नवीन घटक शिकण्याची त्याची तयारी असते, परंतु सुरुवातीला तो थोडासा गोंधळून जातो. वारंवार उजळणी दिल्यास तो दिलेला सर्व अभ्यास अत्यंत व्यवस्थित आणि अचूकपणे करू शकतो.',
            'शिक्षकांनी सांगितलेली कामे तो अतिशय प्रामाणिकपणे पूर्ण करतो आणि नियमांचे योग्य पालन करतो. स्वतःहून फार धडपड करत नसला तरी दिलेला अभ्यास वेळेवर करून दाखवतो.',
        ],
        'awareness_pravah' => [
            'प्राथमिक संकल्पना समजून घेण्यास तो अजूनही बराच वेळ घेतो. स्वतःचे विचार स्पष्टपणे आणि ठामपणे मांडण्यासाठी त्याला सतत शिक्षकांनी प्रेमाने मार्गदर्शन करणे खूप आवश्यक आहे.',
            'शिकवलेल्या बाबी लगेच लक्षात राहण्यासाठी त्याला वारंवार शिक्षकांच्या मदतीची आणि वैयक्तिक लक्ष देण्याची नितांत गरज भासते. तो अनेकदा स्वतःहून प्रश्न विचारताना कचरतो.',
            'प्रश्नांची उत्तरे देताना तो खूपदा गडबडतो किंवा चुकीची उत्तरे देतो. त्याला अधिक प्रोत्साहन देऊन आणि गोष्टी सोप्या करून सांगितल्यास तो योग्य दिशेने प्रगती करू शकतो.',
            'नवीन संकल्पना समजून घेण्यासाठी तो धडपड नक्कीच करतो, पण त्याला अनेकदा सहकाऱ्यांच्या मदतीची खूप गरज लागते. त्याचे लक्ष खेळातून अभ्यासाकडे पूर्णपणे वळवण्यासाठी जास्तीचे प्रयत्न हवेत.',
            'विषयाची केवळ वरवरची ओळख झाली असून त्याची अधिक सखोल उजळणी होणे अत्यंत आवश्यक आहे. स्वतःहून पुढाकार घेण्याची सवय त्याला लावण्यासाठी सतत प्रोत्साहन द्यावे लागेल.',
        ],
        'sensitivity' => [
            'परिचित वातावरणात आणि मित्रमंडळींमध्ये तो खूप छान आणि मोकळेपणाने खेळतो. मात्र, मोठ्या गटात किंवा अनोळखी लोकांशी बोलताना तो अजूनही बराच लाजतो आणि मागे राहतो.',
            'खेळताना किंवा वर्गात कधी कधी त्याच्याकडून नियम मोडले जातात. पण त्याला त्याची चूक प्रेमाने दाखवून दिल्यावर तो ती लगेच मान्य करतो आणि सुधारण्याचा प्रामाणिक प्रयत्न करतो.',
            'आपल्या एक-दोन जवळच्या मित्रांसोबतच जास्त वेळ घालवणे आणि डबा खाणे तो नेहमी पसंत करतो. सगळ्या वर्गासोबत एकरूप होण्यास आणि नवीन मित्र बनवण्यास त्याला थोडा वेळ लागतो.',
            'स्वतःच्या भावना व्यक्त करताना त्याला अनेकदा थोडी अडचण येते. एखादी गोष्ट हवी असल्यास किंवा त्रास होत असल्यास तो स्वतःहून फारसे स्पष्टपणे काहीच बोलत नाही.',
            'तो खोड्या काढून दुसऱ्यांना सहसा मुद्दाम काही त्रास देत नाही. बहुतांश वेळी तो अत्यंत शांत राहून आपल्याच विश्वासात आणि आपल्या आवडत्या गोष्टींमध्ये शांतपणे मग्न राहतो.',
        ],
        'sensitivity_parvat' => [
            'सर्वांशी चांगले वागतो आणि शाळेत सहसा कोणाशीही कोणतेही मोठे भांडण करत नाही. नियम आणि शिस्त पाळण्याचा त्याचा प्रयत्न नेहमीच अतिशय चांगला आणि प्रामाणिक असतो.',
            'बहुतांश वेळा तो शांत आणि समजूतदारपणे वागतो आणि शिक्षकांच्या आज्ञेचे व्यवस्थित पालन करतो. परंतु अनोळखी व्यक्तींसमोर तो स्वतःला व्यक्त करताना थोडाफार संकोचतो.',
            'इतरांच्या भावना त्याला समजतात आणि तो मित्रांना सहसा कधीच दुखावत नाही. दैनंदिन व्यवहारात तो दिलेल्या सूचनांचे पालन करून सामाजिक नियमांशी जुळवून घेण्याचा चांगला प्रयत्न करतो.',
            'मित्रांसोबत खेळताना तो सहकार्याची भावना नक्कीच दाखवतो. वागण्यात थोडा शांतपणा आणि लाजाळूपणा आहे, पण गरजेच्या वेळी तो मित्रांना आवर्जून मदत करतो.',
            'वर्गातील शिस्त पाळतो आणि आपल्या कामाशी नेहमी प्रामाणिक राहतो. मोठ्या समूहात बोलण्याची त्याची फारशी हिंमत होत नसली तरी छोट्या गटात तो खूप खेळीमेळीने वावरतो.',
        ],
        'sensitivity_pravah' => [
            'नवीन परिस्थितीत जुळवून घेण्यास आणि लोकांशी मिसळण्यास त्याला खूप जास्त वेळ लागतो. संवाद साधताना किंवा स्वतःला व्यक्त करताना त्याची खूपच मोठी अडचण होते.',
            'इतरांच्या भावना समजून घेण्यात आणि त्यावर योग्य प्रतिक्रिया देण्यात तो अजूनही खूप संथ आहे. त्याला मित्र बनवण्यासाठी आणि समंजसपणे वागण्यासाठी वारंवार मदतीची गरज भासते.',
            'खेळताना किंवा गटात काम करताना अनेकदा त्याचे मित्रांसोबत छोटेमोठे वाद होतात. नियम पाळण्याची सवय त्याला अद्याप पूर्णपणे लागलेली नाही, त्यासाठी सतत समज द्यावी लागते.',
            'लाजाळू स्वभावामुळे तो स्वतःहून नवीन मित्रांशी अजिबात ओळख करून घेत नाही. बदलत्या परिस्थितीला तोंड देण्यासाठी त्याला चांगलाच आत्मविश्वास मिळवून द्यावा लागेल.',
            'वातावरणाशी एकरूप होताना तो अनेकदा भीती, संकोच किंवा अस्वस्थता दाखवतो. तो प्राथमिक संवादाची सुरुवात करण्यासाठी सर्वस्वी समोरच्या व्यक्तीवर किंवा शिक्षकांवर अवलंबून राहतो.',
        ],
        'creativity' => [
            'साध्या आणि सोप्या कृती तो खूप चांगल्या प्रकारे स्वतःच्या स्वतः पूर्ण करतो. मात्र, एखादी थोडी कठीण किंवा नवीन कल्पक कृती करताना त्याला अनेकदा शिक्षकांच्या मदतीची गरज लागते.',
            'दिलेले चित्र रंगवताना अनेकदा रंगांची चुकीची निवड होते किंवा रंग बाहेर जातात. तरीही प्रत्येक गोष्ट जास्तीत जास्त चांगल्या प्रकारे पूर्ण करण्याचा त्याचा प्रयत्न मात्र नक्कीच प्रामाणिक असतो.',
            'स्वतःकडील साहित्याचा आणि कागदाचा वापर करून नेहमी काहीतरी बनवण्याचा त्याचा चांगला प्रयत्न करतो. पण त्याच्या या रचना बऱ्याचदा खूप साध्या आणि प्राथमिक स्वरूपाच्या असतात.',
            'सर्वांसमोर उभे राहून गोष्ट किंवा गाणे म्हणायला सांगितल्यास तो सुरुवातीला थोडा मागे हटतो. पण गटात सर्वांसोबत असताना तो अतिशय उत्तम प्रकारे आणि जोरात गाणी म्हणतो.',
            'त्याच्या डोक्यात कल्पना नक्कीच खूप असतात पण त्या प्रत्यक्षात उतरवण्यासाठी त्याच्याकडे कौशल्याची थोडी कमी आहे. त्याला यासाठी भरपूर सरावाची आणि शिक्षकांच्या सततच्या मदतीची सक्त गरज असते.',
        ],
        'creativity_parvat' => [
            'दिलेला नमुना किंवा चित्र बघून तो अत्यंत सुबकपणे आणि हुबेहूब त्याचप्रमाणे कृती पूर्ण करण्याचा चांगला प्रयत्न करतो. त्याचे काम बहुतांश वेळा खूप नीटनेटक्या स्वरूपाचे असते.',
            'रंगकाम आणि हस्तकलेत त्याला बऱ्यापैकी आवड आहे असून तो दिलेले काम वेळेत संपवतो. स्वतःची थोडी बहुत कल्पकता त्यात जोडण्याचा त्याचा प्रयत्न निश्चितच चांगला आणि कौतुकास्पद असतो.',
            'साध्या आणि सोप्या कृती तो खूप योग्य प्रकारे पार पडतो. कागदकाम आणि साध्या चित्रकलेत त्याचा हात चांगला बसला आहे, पण त्याला अजूनही क्लिष्ट कामे करण्यासाठी मदतीची गरज लागते.',
            'शिक्षकांनी दिलेल्या सूचनांनुसार तो कलेच्या तासाला व्यवस्थित प्रतिसाद देतो. स्वतःहून जास्त काही वेगळे बनवण्याची धडपड तो करत नसला, तरी तो सांगितलेले काम उत्तम दर्जाचे करतो.',
            'मनापासून आणि भरपूर आवडीने तो कलेचे काम करतो, पण स्वतःच्या कल्पना विस्तारासाठी त्याला थोड्या अधिक मार्गदर्शनाची आणि प्रोत्साहनाची नक्कीच गरज भासते.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा तो प्रयत्न करतो, त्यात सुबकतेचा आणि बारीकसारीक कलाकुसरीचा खूपच अभाव दिसतो. हस्तकलेच्या कामासाठी तो मदतीवर अवलंबून राहतो.',
            'रंगकाम करताना रंग चित्राच्या नेहमीच बाहेर जातात आणि साहित्याचा वापर करताना त्याला अडचण येते. चित्रकलेच्या तासाला नवीन काही रचना करण्यात तो सहसा रस दाखवत नाही.',
            'सूक्ष्म स्नायूंचा आणि बोटांचा समन्वय अजूनही कमी असल्याने त्याला कागद कापणे किंवा पेन्सिलने अचूक आकार काढणे कठीण जाते. या कृती तो पूर्ण करण्यासाठी स्वतःहून फारसा धडपडत नाही.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये तो स्वतःला फारसे रमवू शकत नाही. एखादे साधे चित्र काढायला दिले तरी तो निरुत्साह दाखवतो आणि काम अपूर्ण सोडण्याची त्याची सवय दिसून येते.',
            'कोणतीही नवीन कृती किंवा कला निर्माण करण्याची आवड त्याच्यात अजून अजिबात रुजलेली नाही. त्याच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व सोप्या पद्धतीने शिकवावे लागते.',
        ],
    ],
    'L' => [
        'name' => 'प्रगती आवश्यक (Low)',
        'awareness' => [
            'काही अत्यंत प्राथमिक आणि पायाभूत गोष्टी समजण्यासाठी त्याला इतरांपेक्षा थोडा अधिक वेळ लागतो. शिक्षकांना त्याला या गोष्टी सतत वारंवार आणि खूप सोप्या भाषेत सांगाव्या लागतात, तेव्हाच त्याला त्या थोडेफार समजतात.',
            'अभ्यासात त्याचे लक्ष खूप लवकर विचलित होते आणि तो एका जागी स्थिर बसू शकत नाही. त्याच्या मनात अभ्यासाविषयी रस आणि आवड निर्माण करण्यासाठी शिक्षकांना खूप वेगळे आणि नाविन्यपूर्ण प्रयोग रोज करावे लागतात.',
            'शिक्षकांनी दिलेल्या साध्या आणि सोप्या सूचनांचे योग्य अर्थ लावण्यास त्याला बऱ्याचदा मोठी अडचण येते. कोणतेही काम किंवा अभ्यास स्वतःहून पुढाकार घेऊन करण्याची त्याची वृत्ती अद्याप फारशी विकसित झालेली नाही.',
            'कोणत्याही नवीन गोष्टी किंवा संकल्पना शिकण्याबाबत त्याच्यामध्ये अनेकदा पूर्णपणे उदासिनता आणि निरुत्साह दिसून येतो. त्याला कशातच फारसा रस नसल्याचे त्याच्या रोजच्या वागण्यातून वारंवार स्पष्टपणे जाणवते.',
            'त्याच्या पायाभूत साक्षरता आणि प्राथमिक गणिती संकल्पना अजूनही खूप कच्च्या आणि कमकुवत आहेत. यावर मात करण्यासाठी त्याला खूपच अधिक विशेष प्रयत्नांची आणि वैयक्तिक मार्गदर्शनाची सक्त गरज आहे.',
        ],
        'awareness_parvat' => [
            'शिक्षकांनी सांगितलेली कामे तो बहुतांश वेळा पूर्ण करण्याचा प्रयत्न करतो, पण त्याला अनेकदा पुन्हा पुन्हा सूचना देण्याची आणि सतत मार्गदर्शनाची खूप गरज भासते. उत्तरांमध्ये स्पष्टतेचा स्पष्ट अभाव जाणवतो.',
            'पायाभूत संकल्पना त्याला थोड्याफार समजतात, पण तो त्या ठामपणे सांगताना नेहमीच खूप वेळ घेतो किंवा गोंधळून जातो. भरपूर सराव आणि प्रेमाने समजावून सांगितल्यास त्याच्या उत्तरात सुधारणा होऊ शकते.',
            'शिकवलेल्या बाबी लवकर लक्षात राहण्यासाठी त्याला शिक्षकांच्या मदतीची आणि उजळणीची जास्त गरज लागते. रोजच्या सरावाने तो स्वतःला व्यक्त करण्यासाठी नक्कीच थोडे जास्त मोकळेपणे पुढे येऊ शकेल.',
            'नवीन घटक शिकताना तो थोडा बिचकत असला, तरी वारंवार सराव दिल्यास तो दिलेला अभ्यास पूर्ण करू शकतो. त्याच्याकडून योग्य आणि अचूक अभ्यास करून घेण्यासाठी सतत मागे लागून राहावे लागते.',
            'सर्वसाधारण गोष्टींची जाण त्याला आहे, पण आपले विचार व्यवस्थित शब्दांत मांडण्यासाठी त्याला अजूनही खूप संकोच वाटतो. या संकोची स्वभावामुळे तो अनेकदा स्वतःहून प्रश्नांची उत्तरे देणे जाणीवपूर्वक टाळतो.',
        ],
        'awareness_pravah' => [
            'कोणतीही साधी गोष्ट समजून घेण्यास त्याला इतरांच्या मानाने खूप जास्त वेळ लागतो. आपले विचार स्पष्टपणे मांडण्यासाठी त्याला सतत शिक्षकांनी आधार देणे आणि प्रोत्साहन देणे अत्यंत आवश्यक आहे.',
            'वर्गात शिकवलेल्या गोष्टी त्याच्या फार काळ लक्षात राहत नाहीत आणि तो लवकर विसरून जातो. त्याचे लक्ष अभ्यासात टिकवून ठेवण्यासाठी आणि रुची वाढवण्यासाठी खूप वेगळे आणि विशेष प्रयत्न करावे लागतात.',
            'प्रश्नांची उत्तरे देताना तो नेहमीच खूप गडबडतो किंवा चुकीची उत्तरे देतो. त्याला प्रत्येक गोष्ट अगदी शून्य स्तरापासून व सोप्या पद्धतीने परत-परत समजावून सांगण्याची मोठी गरज भासते.',
            'नवीन संकल्पना समजून घेण्यासाठी तो स्वतःहून फारसा अजिबात धडपडत नाही. त्याचे लक्ष अभ्यासाकडे वळवण्यासाठी आणि तो अभ्यास पूर्ण करून घेण्यासाठी त्याला सतत सहकाऱ्यांच्या किंवा शिक्षकांच्या मदतीची लागते.',
            'पुस्तकातील विषयाची त्याला केवळ वरवरची आणि कमी ओळख झाली असून, त्याची खूप सखोल आणि पुन्हा पुन्हा उजळणी होणे आवश्यक आहे. त्याला स्वतःहून अभ्यासासाठी पुढाकार घेण्याची सवय अजूनही लागलेली नाही.',
        ],
        'sensitivity' => [
            'वर्गात किंवा गटात काम करताना अनेकदा तो इतर मुलांपासून लांब एकटाच गप्प बसणे पसंत करतो. इतर विद्यार्थ्यांशी किंवा शिक्षकांशी त्याचा संवाद खूप कमी आणि मर्यादित आहे.',
            'इतरांच्या भावना किंवा शाळेच्या रोजच्या नियमांबद्दल त्याच्यात फारशी कोणतीही समज नसल्याचे वारंवार त्याच्या वागण्यातून दिसून येते. त्यामुळे तो अनेकदा नकळतपणे नियमांचे उल्लंघन करतो.',
            'वागण्यात थोडा बालिशपणा असल्याने तो लहान-सहान आणि किरकोळ गोष्टींवरून खूप लवकर रडतो किंवा विनाकारण खूप चिडचिड करतो. त्याला समजावणे अनेकदा खूप मोठे आणि कठीण काम होऊन बसते.',
            'इतर मुलांसोबत खेळताना तो अनेकदा खेळाचे नियम स्वतःच्या मनाने मोडतो किंवा कंटाळा आला की मध्येच तो खेळ सोडून निघून जातो, ज्यामुळे इतरांना खूप मोठा त्रास होतो.',
            'नवीन शिक्षक, वर्गातील नवीन मुले किंवा शाळेत आलेल्या अनोळखी लोकांसमोर तो खूप जास्त घाबरल्यासारखा आणि अस्वस्थ वावरतो. त्याच्या मनात अजूनही या गोष्टींबद्दल खूप संकोच आणि अनामिक भीती आहे.',
        ],
        'sensitivity_parvat' => [
            'परिचित वातावरणात तो छान खेळतो, मात्र मोठ्या गटात किंवा अनोळखी लोकांशी बोलताना तो अजूनही पूर्णपणे लाजतो. मित्र बनवण्यास त्याला खूप वेळ लागतो आणि तो मोजक्या मुलांसोबतच राहतो.',
            'खेळताना अनेकदा नियम त्याच्याकडून नकळत मोडले जातात, पण समजून सांगितल्यास तो लगेच ऐकतो. आपल्या एक-दोन जवळच्या मित्रांसोबतच तो डबा खाणे आणि जास्त वेळ घालवणे पसंत करतो.',
            'स्वतःच्या भावना व्यक्त करताना त्याला खूप वेळेस मोठी अडचण येते. स्वतःला त्रास होत असल्यास किंवा काही हवे असल्यास तो स्वतःहून पुढे येऊन कधीही स्पष्टपणे बोलत नाही, त्याला सारखे विचारावे लागते.',
            'तो खोड्या काढून कुणाला त्रास देत नाही, बहुतांश वेळी तो अत्यंत शांत राहतो. मात्र, सर्व वर्गासोबत एकरूप होण्यास त्याला भरपूर वेळ लागतो आणि तो खूपदा आपल्याच विश्वासात आणि विचारात मग्न राहतो.',
            'शाळेतील शिस्त पाळतो, पण मोठ्या समूहात बोलण्याची त्याची हिंमत होत नाही. सहकार्याची भावना असली तरी लाजाळू स्वभावामुळे तो स्वतःहून कोणाला मदत करायला पुढे येत नाही किंवा मदत मागतही नाही.',
        ],
        'sensitivity_pravah' => [
            'नवीन वातावरणात जुळवून घेण्यास त्याला खूप वेळ लागतो आणि संवाद साधताना प्रचंड अडचण येते. इतरांच्या भावना समजून घेण्यात तो खूप संथ आहे आणि योग्य प्रतिक्रिया देण्यास त्याला अजिबात जमत नाही.',
            'खेळताना वारंवार मित्रांसोबत त्याचे वाद होतात आणि नियम पाळण्याची सवय त्याला अजूनही अजिबात लागलेली नाही. त्यासाठी शिक्षकांना सतत त्याच्यावर लक्ष ठेवून त्याला योग्य ती समज द्यावी लागते.',
            'लाजाळू वागणुकीमुळे तो नवीन मित्रांशी अजिबात ओळख करून घेत नाही, आणि एकटाच राहणे कायम पसंत करतो. बदलत्या परिस्थितीला तोंड देण्याचा आत्मविश्वास त्याच्यात अजूनही पूर्णपणे विकसित व्हायचा आहे.',
            'वातावरणाशी एकरूप होताना तो अनेकदा खूप संकोच, भीती किंवा अस्वस्थता दाखवतो. संवादाची सुरुवात करण्यासाठी तो नेहमीच दुसऱ्यांवर अवलंबून असतो आणि स्वतःहून कधीच कोणाशी बोलत नाही.',
            'शाळेत आल्यावर अनेकदा तो खूप रडतो किंवा शांत कोपऱ्यात जाऊन बसतो. समंजसपणे वागण्यासाठी आणि इतर मुलांसोबत जोडण्यासाठी त्याला रोज शिक्षकांच्या प्रेमाने वेळ देऊन समजावण्याची गरज असते.',
        ],
        'creativity' => [
            'कोणतेही दिलेले छोटेसे काम सुरू करण्यासाठी तो पूर्णपणे आणि फक्त शिक्षकांच्या मदतीवर किंवा सूचनेवरच अवलंबून राहतो. तो स्वतःहून अजिबात कोणतेही काम सुरू करू शकत नाही.',
            'रंगकाम किंवा कोणत्याही हस्तकलेत तो अजिबात काडीचाही रस दाखवत नाही. त्याचे हे काम केवळ कागद फाडणे, चुरगळणे किंवा कागदावर अर्थहीन रेष ओढण्यापुरतेच कायम मर्यादित राहिलेले आहे.',
            'कल्पनाशक्तीला किंवा विचारशक्तीला चालना देणाऱ्या साध्या कृती करताना तो नेहमी पूर्णपणे गप्प बसतो आणि कोणताही प्रतिसाद देत नाही. त्याला या गोष्टी समजण्यात खूपच जास्त वेळ लागतो.',
            'शारीरिक हालचालींचे सोपे खेळ सोडल्यास, त्याला इतर कोणत्याही बौद्धिक कृतीत किंवा खेळात खेळताना खूप लवकर कंटाळा येतो. यामुळे तो अशा खेळात सहसा कधीच सहभागी होत नाही.',
            'कागदाची नाव किंवा विमान अशी कोणतीही अत्यंत साधी रचना करण्यासाठी त्याला शिक्षकांना पुन्हा पुन्हा अनेकदा प्रात्यक्षिक करून दाखवावे लागते, तरीही त्याला ते अचूक बनवता येत नाही.',
        ],
        'creativity_parvat' => [
            'साध्या आणि सोप्या कृती तो बऱ्यापैकी पूर्ण करतो, पण कठीण किंवा नवीन कृती करताना त्याला मदतीची गरज लागते. रंगांची थोडी गल्लत होते पण काम पूर्ण करण्याचा त्याचा नेहमी प्रयत्न असतो.',
            'साहित्याचा वापर करून काही तरी बनवण्याचा तो प्रयत्न करतो, पण या रचना अतिशय साध्या असतात. सर्वासमोर गाणे म्हणायला सांगितल्यास तो मागे हटतो, पण गटात सर्वांसोबत असताना छान गातो.',
            'दिलेला नमुना किंवा चित्र बघून त्याच्याच सारखे साधे काम करण्याचा त्याचा प्रयत्न असतो. त्याचे काम अनेकदा योग्य असले तरी তাতে कल्पकतेचा खूप मोठा अभाव असतो आणि सफाई कमी असते.',
            'कागदकाम आणि चित्रकलेत तो फक्त सोपे काम पूर्ण करू शकतो, क्लिष्ट कामे त्याला अजिबात जमत नाहीत. त्याला स्वतःच्या कल्पना विस्तारासाठी अधिक मार्गदर्शनाची आणि प्रोत्साहनाची कायम गरज भासते.',
            'शिक्षकांनी सांगितलेल्या सूचनांनुसार तो साधे काम पूर्ण करू शकतो. पण स्वतःहून जास्त काही वेगळे आणि नवीन बनवण्याची धडपड तो मुळीच करत नाही, तो सांगितलेले काम फक्त कसेबसे संपवतो.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा तो प्रयत्न करतो, आणि त्यात सुबकतेचा खूपच जास्त अभाव दिसतो. हस्तकलेच्या कामासाठी तो पूर्णपणे दुसऱ्यांच्या किंवा शिक्षकांच्या मदतीवरच अवलंबून राहतो.',
            'रंगकाम करताना नेहमीच रंग चित्राच्या पूर्णपणे बाहेर जातात आणि साहित्याचा नीट वापर करताना त्याला मोठी अडचण येते. चित्रकलेच्या तासाला नवीन रचना करण्यात तो अजिबात रस दाखवत नाही.',
            'सूक्ष्म स्नायूंचा समन्वय कमी असल्याने त्याला कागद कापणे किंवा अचूक आकार काढणे खूपच कठीण जाते. या कृती पूर्ण करण्यासाठी तो काहीही प्रयत्न करत नाही आणि काम लगेच सोडून देतो.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये तो स्वतःला अजिबात रमवू शकत नाही. साधे चित्र काढायला दिले तरी तो पूर्ण निरुत्साह दाखवतो आणि काम अर्धवट टाकून किंवा अपूर्ण सोडण्याची त्याची सवय दिसून येते.',
            'कोणतीही नवीन कला निर्माण करण्याची आवड त्याच्यात अजून अजिबात रुजलेली नाही. त्याच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व खूप साध्या पद्धतीने त्याला पुन्हा पुन्हा शिकवावे लागते.',
        ],
    ],
    'VL' => [
        'name' => 'विशेष मदत आवश्यक (Very Low)',
        'awareness' => [
            'ज्ञान आणि विविध संकल्पना ग्रहण करण्याची त्याची क्षमता अद्याप अत्यंत कमी स्तरावर आहे. त्याला अभ्यासाच्या प्रवाहात आणण्यासाठी दैनंदिन पातळीवर खूप विशेष आणि सातत्यपूर्ण मार्गदर्शनाची अत्यंत निकड आहे.',
            'शिक्षकांनी सांगितलेल्या गोष्टी तो वारंवार सांगूनही फार काळ लक्षात ठेवत नाही आणि लवकर विसरतो. वर्गात बसलेले असताना त्याचे लक्ष पूर्णपणे दुसरीकडेच असते आणि अभ्यासात तो अजिबात रस घेत नाही.',
            'अभ्यासाच्या साहित्याचा आणि साधनांचा योग्य प्रकारे वापर करण्यास त्याच्यामध्ये खूपच मोठी असमर्थता दिसून येते. कोणतेही शैक्षणिक साहित्य हाताळताना तो अनेकदा खूप गोंधळलेला आणि दिशाहीन वाटतो.',
            'बौद्धिक किंवा शैक्षणिक प्रकारच्या कोणत्याही अध्ययनामध्ये तो स्वतःहून अजिबात रुची किंवा उत्साह दाखवत नाही. त्याला अभ्यासाला बसवण्यासाठी शिक्षकांना आणि पालकांना रोज खूप मोठी कसरत करावी लागते.',
            'त्याच्या पायाभूत आणि प्राथमिक संकल्पना पूर्णपणे कच्च्या असून त्या अगदी नव्याने आणि शून्यातून शिकवाव्या लागतात. त्याला या सर्व गोष्टी अत्यंत सोप्या भाषेत वारंवार आणि पुन्हा-पुन्हा सांगण्याची गरज आहे.',
        ],
        'awareness_parvat' => [
            'शिक्षकांनी दिलेल्या अगदी सोप्या सूचनांचे पालन करण्याचा तो काही प्रमाणात प्रयत्न करतो, पण त्याला सातत्याने मदतीची गरज लागते. त्याच्या बौद्धिक आणि आकलन क्षमतेत हळूहळू आणि संथ गतीने सुधारणा होण्याची थोडी शक्यता आहे.',
            'पायाभूत बाबींची थोडीफार आणि पुसटशी ओळख त्याला झाली आहे, पण तो त्याबद्दल काहीही सांगताना पूर्णपणे गोंधळून जातो. भरपूर सराव आणि प्रेमाने हाताळल्यास त्याच्या ज्ञानात थोडीफार वाढ होऊ शकते.',
            'शिक्षकांनी वारंवार लक्ष दिल्यावर तो एखादी साधी गोष्ट लक्षात ठेवण्याचा प्रयत्न करतो, पण ती लवकरच विसरूनही जातो. रोजच्या नियमित सरावाने तो पुढील काळात नक्कीच थोडी अधिक प्रगती दाखवू शकेल.',
            'नवीन कोणतेही घटक शिकताना तो खूप जास्त बिचकत आणि घाबरत असला, तरी वारंवार सराव दिल्यास तो दिलेला अभ्यास पूर्ण करू पाहतो. अभ्यासाची सवय लावण्यासाठी त्याच्याकडून अगदी सोपी कामे करून घ्यावी लागतात.',
            'सर्वसाधारण रोजच्या गोष्टींची त्याला थोडी-बहुत जाण आहे, पण आपले विचार शब्दांत मांडणे त्याला जवळजवळ अशक्य वाटते. या स्वभावामुळे तो अनेकदा स्वतःहून कोणतेही उत्तर देणे किंवा बोलणे टाळतो.',
        ],
        'awareness_pravah' => [
            'कोणतीही अगदी साधी गोष्ट समजून घेताना त्याला इतरांपेक्षा असामान्य आणि खूप जास्त वेळ लागतो. आपले प्राथमिक विचार मांडण्यासाठी त्याला सतत शिक्षकांनी आधार आणि शब्द पुरवणे अत्यंत आवश्यक आहे.',
            'शिकवलेल्या गोष्टी त्याच्या अजिबात लक्षात राहत नाहीत आणि तो अभ्यासातील बारकावे पूर्णपणे विसरून जातो. त्याचे लक्ष केवळ काही मिनिटेच टिकते, त्यामुळे त्याला शिकवण्यासाठी खूप विशेष आणि कमी वेळाचे प्रयोग करावे लागतात.',
            'साध्या प्रश्नांची उत्तरे देतानाही तो पूर्णपणे गोंधळतो किंवा फक्त शांत राहून बघत राहतो. त्याला प्रत्येक गोष्ट अगदी शून्य स्तरापासून व खूप सोप्या पद्धतीने परत-परत समजावून सांगण्याची मोठी गरज भासते.',
            'कोणत्याही नवीन शैक्षणिक संकल्पना समजून घेण्यासाठी तो स्वतःहून अजिबात पुढाकार घेत नाही किंवा तशी धडपड करत नाही. त्याला अभ्यासाकडे वळवण्यासाठी सतत शिक्षकांच्या वैयक्तिक मदतीची आणि लक्ष देण्याची गरज लागते.',
            'पुस्तकातील कोणत्याही विषयाची त्याला केवळ नाममात्र ओळख असून, त्याची संपूर्ण व सखोल उजळणी होणे आवश्यक आहे. त्याला स्वतःहून अभ्यासासाठी पुढाकार घेण्याची सवय अजूनही अजिबात लागलेली नाही आणि ती लावणे कठीण आहे.',
        ],
        'sensitivity' => [
            'त्याची संवाद साधण्याची आणि संभाषण क्षमता खूपच कमी आणि प्राथमिक स्तरावर आहे. अनोळखी लोकांसमोर किंवा नवीन शिक्षकांसमोर तो अनेकदा पूर्णपणे गप्प आणि स्तब्ध राहतो.',
            'इतर मुलांच्या गटात मिसळणे तो जाणीवपूर्वक टाळतो आणि नेहमी एकटा बसून स्वतःच्या विश्वातच मग्न राहतो. त्याला इतर मुलांसोबत खेळायला किंवा डबा खायला अजिबात आवडत नाही.',
            'शाळेचे दैनंदिन नियम पाळण्यात आणि शाळेची रोजची दिनचर्या समजून घेण्यात त्याला प्रचंड अडथळे आणि अडचणी येतात. तो वारंवार नियमांचे उल्लंघन करून वर्गात उगीचच गोंधळ घालतो.',
            'इतरांच्या भावनांची त्याला कोणतीही समज किंवा जाणीव नसल्याचे त्याच्या वागणुकीवरून स्पष्टपणे जाणवते. तो अनेकदा खूपच हट्टीपणा करतो आणि स्वतःला हवे तसे वागण्याचा दुराग्रह धरतो.',
            'शाळेतील शिस्त, नियम आणि पद्धत आत्मसात करण्यास त्याला अजूनही अजिबात यश आलेले नाही. त्याला समजावून सांगणे हे शिक्षकांसाठी अनेकदा एक मोठे आणि थकवणारे आव्हान ठरते.',
        ],
        'sensitivity_parvat' => [
            'परिचित वातावरणात तो थोडा वेळ छान खेळतो, मात्र मोठ्या गटात किंवा अनोळखी लोकांशी बोलताना तो स्वतःला लगेच लपवतो. मित्र बनवण्यास त्याला खूप वेळ लागतो आणि तो केवळ एकाच मित्रासोबत नेहमी राहतो.',
            'खेळताना अनेकदा साधे नियम त्याच्याकडून वारंवार मोडले जातात, पण कडक समजून सांगितल्यास तो काही काळ ऐकतो. डबा खातानाही तो एकटाच खाणे पसंत करतो आणि इतरांना स्वतःचे काहीच देत नाही.',
            'स्वतःच्या अगदी प्राथमिक भावना व्यक्त करताना त्याला खूप मोठी अडचण येते. स्वतःला त्रास होत असल्यास किंवा पाणी हवे असल्यास तो स्वतःहून क्वचितच बोलतो, त्याला या गोष्टींसाठी सतत विचारावे लागते.',
            'तो अनेकदा खोड्या काढून कुणाला त्रास देतो, पण विचारल्यावर मात्र आपण काहीच केले नाही असा अत्यंत शांत राहतो. सर्व वर्गासोबत एकरूप होण्यास त्याला भरपूर वेळ लागतो आणि तो अभ्यासाव्यतिरिक्त इतर गोष्टीत मग्न राहतो.',
            'शाळेतील शिस्त पाळण्यासाठी त्याला सतत सूचना द्याव्या लागतात, मोठ्या समूहात तो कधीच उभा राहायला तयार नसतो. सहकार्याची भावना त्याच्यात अत्यंत कमी असून तो स्वतःहून कोणालाही कधी मदत करत नाही.',
        ],
        'sensitivity_pravah' => [
            'नवीन वातावरणात जुळवून घेण्यास त्याला अतोनात वेळ लागतो आणि लहानसा संवाद साधतानाही प्रचंड अडचण आणि मानसिक ताण येतो. इतरांच्या भावना तो अजिबात समजत नाही आणि त्याच्या प्रतिक्रिया अत्यंत चुकीच्या असू शकतात.',
            'खेळताना नेहमीच मित्रांसोबत त्याचे गंभीर वाद आणि भांडणे होतात, नियम पाळण्याची सवय त्याला अजिबात लागलेली नाही आणि तो तसा प्रयत्नच करत नाही. त्यासाठी शिक्षकांना त्याच्यावर प्रत्येक क्षणी लक्ष ठेवावे लागते.',
            'लाजाळू वागणुकीसोबतच त्याच्यात थोडा आक्रस्ताळेपणा असल्याने तो नवीन मित्रांशी ओळख करत नाही आणि सगळ्यांपासून अलिप्त राहतो. परिस्थितीला तोंड देण्याचा आत्मविश्वास त्याच्यात अजूनही पूर्णपणे विकसित व्हायचा आहे.',
            'वातावरणाशी एकरूप होताना तो अनेकदा खूप संकोच, भीती, अस्वस्थता दाखवतो किंवा मोठ्याने रडतो. संवादाची सुरुवात करण्यासाठी तो दुसऱ्यांवर अवलंबून असतो आणि अनेकदा कोणाशीच न बोलण्याचा हट्ट धरून बसतो.',
            'शाळेत आल्यावर अनेकदा तो खूप रडून आईला परत बोलावण्याचा आग्रह धरतो, किंवा वर्गाबाहेर पळून जाण्याचा प्रयत्न करतो. സമंजसपणे वागण्यासाठी आणि रुळावर आणण्यासाठी त्याला रोज शिक्षकांच्या अत्यंत विशेष प्रयत्नांची गरज असते.',
        ],
        'creativity' => [
            'हातापायांच्या आणि बोटांच्या सूक्ष्म स्नायूंचा विकास अजूनही खूप कमी असल्याने त्याला अतिशय साध्या कृती करतानाही खूप त्रास होतो. त्याला सर्व कामात पूर्णपणे दुसऱ्यांवर अवलंबून राहावे लागते.',
            'कागद योग्य प्रकारे पकडणे, पेन्सिल व्यवस्थित धरणे किंवा सरळ रेष मारणे यासारख्या अत्यंत बारीक आणि प्राथमिक कामात त्याला बरीच अडचण येते. त्याचे काम अतिशय अस्वच्छ असते.',
            'त्याची कल्पनाशक्ती खूपच मर्यादित आणि कमकुवत आहे. तो स्वतःहून कोणतीही नवीन कृती किंवा रचना करत नाही आणि शिक्षकांनी सांगितल्यावरही त्याला काहीच सुचत नाही.',
            'शिक्षकांनी स्वतः त्याच्या हाताला धरून काम करवून घेतल्याशिवाय तो कोणत्याही कृतीत किंवा खेळात अजिबात सहभाग घेत नाही. तो अनेकदा काम करण्यास स्पष्ट नकार देतो.',
            'त्याच्यातील सर्जनशील आणि कलात्मक क्षमतांचा विकास खूपच प्रारंभिक स्तरावर थांबलेला आहे. त्यात सुधारणा करण्यासाठी त्याला अगदी सुरुवातीपासून व जादा वेळे देऊन हस्तकला शिकवावी लागेल.',
        ],
        'creativity_parvat' => [
            'साध्या आणि भौतिक कृती तो कसेबसे पूर्ण करतो, पण कोणतीही थोडी कठीण कृती करताना त्याला पूर्णपणे मदतीची गरज लागते. रंगांची ओळख त्याला अद्याप स्पष्ट नसल्याने काम नेहमी चुकीचे आणि अस्वच्छ असते.',
            'साहित्याचा नुसता वापर करून काही तरी वेडेवाकडे बनवण्याचा तो प्रयत्न करतो, पण या रचना अतिशय अर्थहीन असतात. सर्वासमोर गाणे म्हणायला सांगितल्यास तो लगेच रडायला लागतो आणि काहीच बोलत नाही.',
            'दिलेला नमुना बघून त्याच्यासारखे काम करण्याचा त्याचा प्रयत्न असतो, पण सूक्ष्म स्नायूंचा विकास कमी असल्याने ते जमत नाही. त्याचे काम नेहमी अर्धवट किंवा चुकीचे असते आणि তাতে कल्पकतेचा खूप मोठा अभाव असतो.',
            'कागदकाम आणि चित्रकलेत तो फक्त कागद चुरगळणे असेच काम करू शकतो, क्लिष्ट कामे त्याला अजिबात जमत नाहीत. त्याला स्वतःच्या कल्पना विस्तारासाठी अत्यंत प्राथमिक आणि विशेष मार्गदर्शनाची गरज भासते.',
            'शिक्षकांनी दिलेल्या सूचना त्याला पूर्णपणे समजत नाहीत आणि तो काम करताना दिशाहीन होतो. स्वतःहून काही वेगळे बनवण्याची धडपड तो मुळीच करत नाही, तो फक्त समोर दिलेले काम कसेतरी संपवण्याच्या घाईत असतो.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची नक्कल करणेही त्याला अजिबात जमत नाही आणि त्यात सुबकतेचा १०० टक्के अभाव दिसतो. हस्तकलेच्या कोणत्याही कामासाठी तो पूर्णपणे आणि फक्त शिक्षकांच्या मदतीवरच अवलंबून राहतो.',
            'रंगकाम करताना नेहमीच रंग चित्राच्या पूर्णपणे बाहेर जातात, कागद फाटतो आणि साहित्याचा नीट वापर करताना त्याला मोठी अडचण येते. चित्रकलेच्या तासाला तो केवळ रेषे मारून वही खराब करण्यातच मग्न असतो.',
            'सूक्ष्म स्नायूंचा समन्वय अतिशय कमी असल्याने त्याला कागद कापणे किंवा पेन्सिलने आकार काढणे अशक्य जाते. या कृती पूर्ण करण्यासाठी तो काहीही सकारात्मक प्रयत्न करत नाही आणि काम लगेच सोडून रडू लागतो.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये तो स्वतःला अजिबात रमवू शकत नाही आणि इतर मुलांनाही काम करू देत नाही. चित्र काढायला दिले तरी तो निरुत्साह दाखवतो आणि काम अर्धवट टाकून वर्गात पळण्याची त्याची सवय दिसून येते.',
            'कोणतीही साधी कला निर्माण करण्याची क्षमता त्याच्यात अजून अजिबात रुजलेली नाही. त्याच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व खूप साध्या पद्धतीने त्याला हाताला धरून पुन्हा पुन्हा जास्तीचा वेळ देऊन शिकवावे लागते.',
        ],
    ],
];

