            'शिकवलेल्या घटकांबद्दलची तिची समज खूपच स्पष्ट आणि पक्की आहे. स्वतःहून नवीन माहिती शोधून काढण्याची आणि ती वर्गात सर्वांसमोर सविस्तरपणे सांगण्याची तिची हातोटी विलक्षण आहे, ज्यामुळे ती नेहमी अभ्यासात अग्रेसर असते.',
            'कोणत्याही नवीन विषयाचे आकलन अतिशय जलद गतीने करण्याची तिची क्षमता वाखाणण्याजोगी आहे. वर्गातील चर्चेत अत्यंत मार्मिक मुद्दे उपस्थित करून ती नेहमीच स्वतःची वेगळी आणि हुशार ओळख निर्माण करते.',
            'परिसरातील घडामोडी आणि शैक्षणिक विषयांचे अत्यंत बारकाईने निरीक्षण करून त्यातील संकल्पना स्पष्टपणे समजून घेण्याचा तिचा कल नेहमी दिसून येते. स्वतःच्या ज्ञानाचा उपयोग ती अतिशय कल्पकतेने करते.',
            'नव-नवीन गोष्टी शिकण्याची आणि त्या इतरांनाही अतिशय साध्या भाषेत समजावून सांगण्याची तिची धडपड प्रकर्षाने जाणवते. ती खऱ्या अर्थाने एक हुशार आणि जिज्ञासू वृत्तीचा आदर्श विद्यार्थिनी आहे.',
        ],
        'awareness_parvat' => [
            'विषयाचे चांगले आकलन असून शिक्षकांनी दिलेल्या सूचना आणि नियमांचे ती बहुतांश वेळा अतिशय व्यवस्थित पालन करते. नवीन गोष्टी शिकण्यासाठी ती नेहमी उत्साही असते आणि साध्या प्रश्नांची अचूक उत्तरे देते.',
            'शिकवलेला भाग समजून घेऊन त्यावर विचार करण्याची वृत्ती दिसून येते. स्वतःहून फार प्रश्न विचारत नसला तरी विचारलेल्या प्रश्नांची योग्य उत्तरे देण्यात तिचा हातखंडा चांगला आहे.',
            'पायाभूत संकल्पना स्पष्ट आहेत आणि दैनंदिन अभ्यासात ती नेहमी सातत्य ठेवते. थोड्या अधिक वाचनाची आणि अभ्यासाची सवय लावल्यास ती अधिक प्रगल्भ उत्तरे देऊ शकेल असे वाटते.',
            'परिसरातील गोष्टींची चांगली माहिती आहे आणि शाळेतील कामकाजात ती उत्साहाने भाग घेते. स्वतःचे विचार मांडण्यासाठी ती नेहमी योग्य शब्दांची निवड करण्याचा प्रामाणिक प्रयत्न करते.',
            'शिक्षकांनी सांगितलेले काम ती अत्यंत प्रामाणिकपणे आणि वेळेवर पूर्ण करते. नवीन शैक्षणिक संकल्पना समजून घेण्यास ती उत्सुक असते, पण त्यासाठी तिला थोडा वेळ लागतो.',
        ],
        'awareness_pravah' => [
            'प्राथमिक संकल्पनांची समज निर्माण होत आहे, मात्र स्वतःचे विचार स्पष्टपणे मांडताना तिला सरावाची गरज भासते. शिक्षकांनी वारंवार मार्गदर्शन केल्यावर ती कृती पूर्ण करण्याचा चांगला प्रयत्न करते.',
            'पायाभूत बाबी समजतात पण त्या व्यक्त करताना थोडा संकोच दिसून येते. प्रश्नाची उत्तरे देण्यासाठी तिला थोडा प्रवृत्त करावे लागते, त्यानंतर ती योग्य आणि बऱ्यापैकी अचूक उत्तरे देते.',
            'शिकवलेल्या बाबी लगेच आत्मसात करण्यासाठी थोडा अधिक वेळ आणि सरावाची आवश्यकता आहे. वैयक्तिक लक्ष दिल्यास ती दिलेल्या सूचनांचे टप्प्याटप्प्याने आणि हळुवारपणे पालन करते.',
            'नवीन संकल्पना समजून घेण्यासाठी ती धडपड करते, पण तिला सहकाऱ्यांच्या किंवा शिक्षकांच्या मदतीची अनेकदा गरज लागते. तिचे अभ्यासातील लक्ष केंद्रित करण्यासाठी अधिक प्रयोगांची गरज आहे.',
            'विषयाची केवळ प्राथमिक ओळख झाली असून अधिक स्पष्टतेसाठी सखोल उजळणी आवश्यक आहे. स्वतःहून पुढाकार घेऊन नवीन गोष्टी शिकण्याची वृत्ती विकसित करण्यासाठी सतत प्रोत्साहन द्यावे लागेल.',
        ],
        'sensitivity' => [
            'गटात किंवा समाजात वावरताना ती अतिशय समझदारपणा व समजूतदारपणा दाखवतो. इतरांच्या भावनांचा आदर करणे, लहानांवर प्रेम करणे आणि सर्वांना सोबत घेऊन जाण्याचा तिचा स्वभाव सर्वांना भावतो.',
            'मित्र-मैत्रिणींच्या अडीअडचणींना धावून जाण्याची आणि त्यांना मदत करण्याची तिची वृत्ती खूपच छान आहे. शाळेतील नियम ती स्वतः तर पाळतोच पण इतरांनाही ते पाळण्यासाठी खूप गोड शब्दांत प्रवृत्त करते.',
            'कोणत्याही नवीन परिस्थितीत स्वतःला जुळवून घेण्याचे तिचे कौशल्य विलक्षण आहे. सांस्कृतिक आणि सामाजिक कार्यक्रमात ती अत्यंत संवेदनशीलपणे आणि जबाबदारीने स्वतःचा सहभाग प्रभावीपणे नोंदवते.',
            'कुटुंब, शाळा आणि परिसर या सर्वच ठिकाणी ती अत्यंत आदराने आणि नम्रतेने वावरतो. त्याच्यातील भावनिक प्रगल्भता आणि नेतृत्व गुण तिच्या वयाच्या मानाने अतिशय उत्कृष्ट आणि कौतुकास्पद आहेत.',
            'वागण्या-बोलण्यातला गोडवा आणि सर्वांशी मिळून-मिसळून राहण्याची वृत्ती यामुळे ती वर्गात सर्वांचा लाडका आहे. इतरांच्या दुःखात हळवा होणारा आणि आनंदात सहभागी होणारा हा एक अतिशय गुणी विद्यार्थिनी आहे.',
        ],
        'sensitivity_parvat' => [
            'सर्वांशी चांगले वागते आणि शाळेत कोणाशीही सहसा भांडण करत नाही. नियम आणि शिस्त पाळण्याचा तिचा प्रयत्न नेहमी प्रामाणिक असते, मात्र गटात सर्वांचे नेतृत्व करण्यास ती कधीकधी मागे हटतो.',
            'बहुतांश वेळा ती समजूतदारपणे वागते आणि शिक्षकांच्या आज्ञेचे पालन करते. ओळखीच्या मित्रांसोबत ती खूप छान वावरतो, पण अनोळखी व्यक्तींसमोर ती स्वतःला व्यक्त करताना थोडाफार संकोच बाळगतो.',
            'इतरांच्या भावना तिला समजतात आणि ती सहसा कोणाला दुखावत नाही. दैनंदिन व्यवहारात सावधगिरी बाळगून ती दिलेल्या सूचनांचे पालन करत सामाजिक नियमांशी जुळवून घेण्याचा उत्तम प्रयत्न करते.',
            'मित्रांसोबत खेळताना किंवा डबा खाताना ती सहकार्याची भावना दाखवतो. वागण्यात थोडा शांतपणा आहे, पण जेव्हा गरजेची वेळ येते तेव्हा ती नक्कीच आपल्या सहकाऱ्यांना योग्य ती मदत करते.',
            'वर्गातील शिस्त पाळतो आणि आपल्या कामाशी प्रामाणिक राहते. मोठ्या समूहात बोलण्याची तिची फारशी हिंमत होत नाही, तरीही छोट्या गटात ती अत्यंत खेळीमेळीने आणि समजुतीने सर्वांसोबत वावरतो.',
        ],
        'sensitivity_pravah' => [
            'सामाजिक परिस्थितीशी जुळवून घेण्यास तिला थोडा वेळ लागतो. संवाद साधताना किंवा स्वतःला व्यक्त करताना तिची खूपच अडचण होते आणि ती मोठ्या समूहात अनेकदा एकटाच राहणे पसंत करते.',
            'इतरांच्या भावना समजून घेण्यात आणि त्यावर प्रतिक्रिया देण्यात ती थोडा संथ आहे. रागावर नियंत्रण मिळवण्यासाठी आणि समंजसपणे वागण्यासाठी तिला वारंवार शिक्षकांच्या आणि पालकांच्या वैयक्तिक मदतीची गरज भासते.',
            'खेळताना किंवा गटात काम करताना अनेकदा तिचे मित्रांसोबत छोटेमोठे वाद होतात. नियम पाळण्याची सवय तिला अद्याप पूर्णपणे लागलेली नाही, त्यासाठी तिला सतत प्रेमाने आणि समजून सांगावे लागते.',
            'संकोची स्वभावामुळे ती स्वतःहून नवीन मित्रांशी ओळख करून घेत नाही. बदलत्या परिस्थितीला तोंड देण्याची तिची तयारी अद्याप पूर्ण नाहीये, त्यामुळे तिला आत्मविश्वास मिळवून देण्यासाठी जास्त खटाटोप करावी लागते.',
            'वातावरणाशी एकरूप होताना ती अनेकदा भीती किंवा अस्वस्थता दाखवतो. प्राथमिक संवादाची सुरुवात करण्यासाठी ती पूर्णपणे समोरच्या व्यक्तीवर अवलंबून राहते, स्वतःहून पुढे येऊन बोलण्यास बिचकतो.',
        ],
        'creativity' => [
            'कोणत्याही कामात नवनिर्मिती करण्याची तिची क्षमता थक्क करणारी आहे. दिलेल्या साधनांचा वापर करून ती अतिशय कल्पक आणि हुबेहूब रचना तयार करते, ज्यामुळे तिची कलाकृती नेहमी वर्गात सर्वात वेगळी आणि सुंदर ठरते.',
            'चित्रकला, मातीकाम आणि हस्तकला यात त्याच्याकडे जन्मजातच खूप चांगली कला आहे. रंगसंगतीची निवड, साहित्याची योग्य जुळवाजुळव आणि बारकावे टिपण्याची तिची पद्धत अत्यंत प्रगल्भ आणि सर्वांसाठी प्रेरणादायी आहे.',
            'स्वतःच्या डोक्याने विचार करून नेहमी काहीतरी नवीन आणि हटके बनवण्याचा तिचा प्रयत्न वाखाणण्याजोगा आहे. गोष्टी रचणे, नाट्यीकरण करणे किंवा गाणी म्हणण्यात तिची सर्जनशीलता एकदम उच्च पातळीवर दिसून येते.',
            'कोणतीही साधी वस्तू दिली तरी तिच्यातून ती एक सुरेख मॉडेल किंवा खेळणी तयार करू शकतो. कलेच्या विविध क्षेत्रात ती अत्यंत हुशारीने आणि कल्पकतेने आपला ठसा उमटवतो, तिचे मन अतिशय सृजनशील आहे.',
            'विचार करण्याची पद्धत चौकटीबाहेरची असून ती प्रत्येक गोष्टीकडे एका नवीन कलात्मक दृष्टिकोनातून बघते. तिच्या हाताला अतिशय उत्तम वळण असून ती सुरेख आणि सुबक कलाकुसर करण्यात अतिशय निपुण आहे.',
        ],
        'creativity_parvat' => [
            'दिलेला नमुना बघून ती अत्यंत सुबकपणे आणि हुबेहूब त्याचप्रमाणे कृती पूर्ण करते. साहित्याचा वापर काळजीपूर्वक करून ती चांगल्या आणि नीटनेटक्या रचना तयार करते, पण स्वतःहून वेगळी कल्पना लढवत नाही.',
            'रंगकाम आणि हस्तकलेत तिला बऱ्यापैकी रुची आहे असून ती दिलेले काम वेळेत आणि स्वच्छपणे संपवतो. स्वतःची थोडी कल्पकता त्यात जोडण्याचा तिचा प्रयत्न निश्चितच चांगला असते, ज्यात ती यशस्वीही होतो.',
            'साध्या आणि सोप्या कृती ती योग्य प्रकारे पार पडतो. कागदकाम आणि साध्या चित्रकलेत तिचा हात चांगला बसला आहे. मात्र, अत्यंत क्लिष्ट आणि गुंतागुंतीच्या रचना करताना तिला थोड्या मार्गदर्शनाची गरज लागते.',
            'शिक्षकांनी दिलेल्या सूचनांनुसार ती कलेच्या तासाला चांगला प्रतिसाद देते. स्वतःहून अतिशय वेगळे काही बनवण्याची धडपड ती फारशी करत नाही, तरीही तिचे काम नेहमीच उत्तम दर्जाचे आणि व्यवस्थित असते.',
            'मनापासून आणि आवडीने ती कलेचे काम करते, पण कल्पना विस्तारासाठी तिला थोड्या प्रोत्साहनाची गरज आहे. विविध रंग आणि आकारांचा ती चांगला वापर करून कलाकृती निश्चितच छान खुलवून दाखवू शकतो.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा ती प्रयत्न करते, त्यात सुबकतेचा आणि कल्पकतेचा खूपच अभाव दिसतो. हस्तकलेचे आणि चित्रकलेचे काम पूर्ण करण्यासाठी ती पूर्णपणे मदतीवर अवलंबून राहते.',
            'रंगकाम करताना रंग बाहेर जातात आणि साहित्याचा वापर करताना तिला खूप अडचण येते. स्वतःहून कोणतीही नवीन रचना करण्याचा ती अजिबात विचार करत नाही आणि या तासाला अनेकदा कंटाळा करते.',
            'सूक्ष्म स्नायूंचा विकास अजूनही कमी असल्याने तिला कागद कापणे, दुमडणे किंवा पेन्सिलने आकार काढणे खूप कठीण जाते. साध्या कृती पूर्ण करण्यासाठी तिला हाताला धरून वारंवार सराव द्यावा लागतो.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये ती स्वतःला फारसे रमवू शकत नाही. एखादे सोपे चित्र काढायला दिले तरी ती लगेच हार मानतो आणि काम अर्धवट सोडून देण्याची वैतागलेली वृत्ती त्याच्यात दिसून येते.',
            'कोणतीही नवीन कृती किंवा कला निर्माण करण्याची आवड त्याच्यात अजून रुजलेली नाही. त्याच्यातील कलागुणांना वाव देण्यासाठी अगदी प्राथमिक स्तरापासून आणि अत्यंत सोप्या पद्धतीचा वापर करून शिकवावे लागते.',
        ],
    ],
    'H' => [
        'name' => 'उत्तम (High)',
        'awareness' => [
            'विषयाची एकदम सखोल जाण तिला आहे आणि शिकवलेला भाग ती चटकन आत्मसात करते. ती स्वतःहून नवीन गोष्टी विचारून समजून घेण्याचा खूप प्रामाणिक प्रयत्न करते.',
            'वर्गात शिकवलेले घटक लगेच लक्षात ठेवण्याची तिची हातोटी खूप चांगली आहे. स्वतः शिकलेली माहिती ती इतरांनाही सांगण्यात आणि समजावून देण्यात नेहमीच पुढाकार घेते.',
            'नव्या संकल्पना व घटकांबद्दल तिचा समज खूप पक्का आहे, ज्यामुळे ती परीक्षेत चांगले गुण मिळवतो. विचारलेल्या बहुतांश प्रश्नांची अचूक उत्तरे ती पटकन आणि न घाबरता देते.',
            'अभ्यासात ती खूप हुशार असून परिसरातील नवनवीन गोष्टींचे ती नेहमी बारकाईने निरीक्षण करते. या निरीक्षणातून ती अनेक चांगले निष्कर्ष स्वतःहून काढतो.',
            'कोणतीही नवीन माहिती मिळवण्याची आणि ती कायमस्वरूपी लक्षात ठेवण्याची तिची धडपड वाखाणण्याजोगी आहे. सर्वांच्या मते ती एक अत्यंत हुशार आणि अभ्यासू विद्यार्थिनी आहे.',
        ],
        'awareness_parvat' => [
            'शिक्षकांनी सांगितलेली कामे ती अतिशय प्रामाणिकपणे पूर्ण करते आणि नियमांचे योग्य पालन करते. स्वतःहून फार धडपड करत नसला तरी दिलेला अभ्यास वेळेवर करून दाखवतो.',
            'शिकवलेल्या गोष्टी तिला बहुतांश वेळा समजतात, मात्र त्या ठामपणे सांगण्यासाठी तिला शिक्षकांच्या आधाराची गरज भासते. उत्तरांमध्ये थोडीफार सुधारणा केल्यास ती खूप चांगली प्रगती करेल.',
            'पायाभूत बाबी समजण्यात तिला बऱ्यापैकी गती आहे, पण अजूनही वाचन आणि लेखनात तिला सरावाची गरज आहे. सरावाने ती नक्कीच अधिक चांगल्या प्रकारे स्वतःला व्यक्त करू शकेल.',
            'रोजच्या अभ्यासाव्यतिरिक्त ती इतर अवांतर गोष्टींतही चांगला रस घेते. प्रश्न विचारल्यास ती शांतपणे आणि बऱ्यापैकी बरोबर उत्तरे देते, ज्यात अजून प्रगल्भता येणे अपेक्षित आहे.',
            'नवीन घटक शिकण्याची तिची तयारी असते, परंतु सुरुवातीला ती थोडासा गोंधळून जाते. वारंवार उजळणी दिल्यास ती दिलेला सर्व अभ्यास अत्यंत व्यवस्थित आणि अचूकपणे करू शकतो.',
        ],
        'awareness_pravah' => [
            'प्राथमिक संकल्पना समजून घेण्यास ती अजूनही बराच वेळ घेते. स्वतःचे विचार स्पष्टपणे आणि ठामपणे मांडण्यासाठी तिला सतत शिक्षकांनी प्रेमाने मार्गदर्शन करणे खूप आवश्यक आहे.',
            'शिकवलेल्या बाबी लगेच लक्षात राहण्यासाठी तिला वारंवार शिक्षकांच्या मदतीची आणि वैयक्तिक लक्ष देण्याची नितांत गरज भासते. ती अनेकदा स्वतःहून प्रश्न विचारताना कचरतो.',
            'प्रश्नांची उत्तरे देताना ती खूपदा गडबडतो किंवा चुकीची उत्तरे देते. तिला अधिक प्रोत्साहन देऊन आणि गोष्टी सोप्या करून सांगितल्यास ती योग्य दिशेने प्रगती करू शकतो.',
            'नवीन संकल्पना समजून घेण्यासाठी ती धडपड नक्कीच करते, पण तिला अनेकदा सहकाऱ्यांच्या मदतीची खूप गरज लागते. तिचे लक्ष खेळातून अभ्यासाकडे पूर्णपणे वळवण्यासाठी जास्तीचे प्रयत्न हवेत.',
            'विषयाची केवळ वरवरची ओळख झाली असून तिची अधिक सखोल उजळणी होणे अत्यंत आवश्यक आहे. स्वतःहून पुढाकार घेण्याची सवय तिला लावण्यासाठी सतत प्रोत्साहन द्यावे लागेल.',
        ],
        'sensitivity' => [
            'मित्रांसोबत वागताना ती नेहमी खूप समझदारपणा आणि सामंजस्याची भूमिका दाखवतो. शाळेत रोज आनंदाने येते आणि सर्वांशी खूप प्रेमाने आणि आदराने वागते.',
            'इतरांच्या भावनांचा आणि अडचणींचा ती खूप आदर करते. वर्गात कोणालाही मदतीची गरज लागली तर ती अत्यंत निस्वार्थीपणे आणि लगेच धावून जाते.',
            'गटात काम करताना स्वतःचे नेतृत्व गुण प्रस्थापित करून सर्वांना बरोबर घेऊन जाण्याची तिची सवय खूपच छान आणि आदर्शवत आहे.',
            'आजारी किंवा अभ्यासात कमजोर असलेल्या मित्रांची काळजी घेण्यात आणि त्यांना अभ्यासात मदत करण्यात ती नेहमीच पुढे राहते.',
            'शाळेतील सर्व नियम पाळण्यात आणि शिक्षकांचा आदर करण्यात ती एक उत्तम आणि आदर्श विद्यार्थिनी आहे. मोठ्या व्यक्तींशी ती अतिशय नम्रपणे आणि आदराने बोलते.',
        ],
        'sensitivity_parvat' => [
            'सर्वांशी चांगले वागते आणि शाळेत सहसा कोणाशीही कोणतेही मोठे भांडण करत नाही. नियम आणि शिस्त पाळण्याचा तिचा प्रयत्न नेहमीच अतिशय चांगला आणि प्रामाणिक असते.',
            'बहुतांश वेळा ती शांत आणि समजूतदारपणे वागते आणि शिक्षकांच्या आज्ञेचे व्यवस्थित पालन करते. परंतु अनोळखी व्यक्तींसमोर ती स्वतःला व्यक्त करताना थोडाफार संकोचतो.',
            'इतरांच्या भावना तिला समजतात आणि ती मित्रांना सहसा कधीच दुखावत नाही. दैनंदिन व्यवहारात ती दिलेल्या सूचनांचे पालन करून सामाजिक नियमांशी जुळवून घेण्याचा चांगला प्रयत्न करते.',
            'मित्रांसोबत खेळताना ती सहकार्याची भावना नक्कीच दाखवतो. वागण्यात थोडा शांतपणा आणि लाजाळूपणा आहे, पण गरजेच्या वेळी ती मित्रांना आवर्जून मदत करते.',
            'वर्गातील शिस्त पाळतो आणि आपल्या कामाशी नेहमी प्रामाणिक राहते. मोठ्या समूहात बोलण्याची तिची फारशी हिंमत होत नसली तरी छोट्या गटात ती खूप खेळीमेळीने वावरतो.',
        ],
        'sensitivity_pravah' => [
            'नवीन परिस्थितीत जुळवून घेण्यास आणि लोकांशी मिसळण्यास तिला खूप जास्त वेळ लागतो. संवाद साधताना किंवा स्वतःला व्यक्त करताना तिची खूपच मोठी अडचण होते.',
            'इतरांच्या भावना समजून घेण्यात आणि त्यावर योग्य प्रतिक्रिया देण्यात ती अजूनही खूप संथ आहे. तिला मित्र बनवण्यासाठी आणि समंजसपणे वागण्यासाठी वारंवार मदतीची गरज भासते.',
            'खेळताना किंवा गटात काम करताना अनेकदा तिचे मित्रांसोबत छोटेमोठे वाद होतात. नियम पाळण्याची सवय तिला अद्याप पूर्णपणे लागलेली नाही, त्यासाठी सतत समज द्यावी लागते.',
            'लाजाळू स्वभावामुळे ती स्वतःहून नवीन मित्रांशी अजिबात ओळख करून घेत नाही. बदलत्या परिस्थितीला तोंड देण्यासाठी तिला चांगलाच आत्मविश्वास मिळवून द्यावा लागेल.',
            'वातावरणाशी एकरूप होताना ती अनेकदा भीती, संकोच किंवा अस्वस्थता दाखवतो. ती प्राथमिक संवादाची सुरुवात करण्यासाठी सर्वस्वी समोरच्या व्यक्तीवर किंवा शिक्षकांवर अवलंबून राहते.',
        ],
        'creativity' => [
            'कोणतेही काम दिले तर ती स्वतःच्या डोक्याने विचार करून त्यातून नवीन काहीतरी सुंदर आणि आकर्षित ठेवणारी गोष्ट नक्कीच बनवून दाखवतो. तिची ही कला खूप छान आहे.',
            'मातीकाम आणि चित्रकलेत तिचा हातखंडा खूपच छान आणि सफाईदार आहे. रंगसंगतीची आणि आकारांची अत्यंत उत्तम जाण तिच्या प्रत्येक रचनेत स्पष्टपणे दिसून येते.',
            'कागदकाम व विविध हस्तकलेतून ती खूप सुंदर आणि कल्पक वस्तू अत्यंत सफाईने बनवतो. त्या वस्तू बघून इतर मुले देखील त्याच्याकडून तसे काम करायला नक्कीच शिकतात.',
            'दिलेल्या साहित्याचा अत्यंत कल्पक वापर करून ती नेहमी काहीतरी हटके आणि नवीन बनवण्याचा प्रामाणिक प्रयत्न करते, आणि त्यात ती बर्‍याच अंशी यशस्वी देखील ठरतो.',
            'गाणी आणि गोष्टींच्या माध्यमातून स्वतःचे विचार अतिशय नाट्यपूर्णरीत्या मांडण्यात ती वर्गात सगळ्यात भारी आहे. त्याच्यातील नाट्य आणि कलागुण खूपच विलक्षण आहेत.',
        ],
        'creativity_parvat' => [
            'दिलेला नमुना किंवा चित्र बघून ती अत्यंत सुबकपणे आणि हुबेहूब त्याचप्रमाणे कृती पूर्ण करण्याचा चांगला प्रयत्न करते. तिचे काम बहुतांश वेळा खूप नीटनेटक्या स्वरूपाचे असते.',
            'रंगकाम आणि हस्तकलेत तिला बऱ्यापैकी आवड आहे असून ती दिलेले काम वेळेत संपवतो. स्वतःची थोडी बहुत कल्पकता त्यात जोडण्याचा तिचा प्रयत्न निश्चितच चांगला आणि कौतुकास्पद असते.',
            'साध्या आणि सोप्या कृती ती खूप योग्य प्रकारे पार पडतो. कागदकाम आणि साध्या चित्रकलेत तिचा हात चांगला बसला आहे, पण तिला अजूनही क्लिष्ट कामे करण्यासाठी मदतीची गरज लागते.',
            'शिक्षकांनी दिलेल्या सूचनांनुसार ती कलेच्या तासाला व्यवस्थित प्रतिसाद देते. स्वतःहून जास्त काही वेगळे बनवण्याची धडपड ती करत नसला, तरी ती सांगितलेले काम उत्तम दर्जाचे करते.',
            'मनापासून आणि भरपूर आवडीने ती कलेचे काम करते, पण स्वतःच्या कल्पना विस्तारासाठी तिला थोड्या अधिक मार्गदर्शनाची आणि प्रोत्साहनाची नक्कीच गरज भासते.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा ती प्रयत्न करते, त्यात सुबकतेचा आणि बारीकसारीक कलाकुसरीचा खूपच अभाव दिसतो. हस्तकलेच्या कामासाठी ती मदतीवर अवलंबून राहते.',
            'रंगकाम करताना रंग चित्राच्या नेहमीच बाहेर जातात आणि साहित्याचा वापर करताना तिला अडचण येते. चित्रकलेच्या तासाला नवीन काही रचना करण्यात ती सहसा रस दाखवत नाही.',
            'सूक्ष्म स्नायूंचा आणि बोटांचा समन्वय अजूनही कमी असल्याने तिला कागद कापणे किंवा पेन्सिलने अचूक आकार काढणे कठीण जाते. या कृती ती पूर्ण करण्यासाठी स्वतःहून फारसा धडपडत नाही.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये ती स्वतःला फारसे रमवू शकत नाही. एखादे साधे चित्र काढायला दिले तरी ती निरुत्साह दाखवतो आणि काम अपूर्ण सोडण्याची तिची सवय दिसून येते.',
            'कोणतीही नवीन कृती किंवा कला निर्माण करण्याची आवड त्याच्यात अजून अजिबात रुजलेली नाही. तिच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व सोप्या पद्धतीने शिकवावे लागते.',
        ],
    ],
    'M' => [
        'name' => 'मध्यम (Medium)',
        'awareness' => [
            'काही महत्त्वाच्या आणि पायाभूत संकल्पना तिला बऱ्यापैकी समजतात, मात्र त्या ठामपणे सांगताना ती थोडा विचार आणि वेळ घेते. वारंवार सराव दिल्यास तिच्या उत्तरात नक्कीच अचूकता येते.',
            'सांगितलेले काम ती पूर्ण करते पण बऱ्याचदा तिचे लक्ष थोडे विचलित होते. तिला वेळेवर काम पूर्ण करण्यासाठी शिक्षकांनी सतत आठवण करून देत राहावे लागते, ज्यामुळे ती काम पूर्ण करते.',
            'एखादी नवीन गोष्ट किंवा संकल्पना पटकन समजायला तिला थोडा वेळ लागतो. मात्र, शिक्षकांनी लक्ष देऊन त्याच्याकडून सतत सराव करून घेतल्यास ती गोष्ट ती नक्कीच आत्मसात करते.',
            'बऱ्याच वेळा ती शांत बसून राहणे पसंत करते, पण जेव्हा तिला उत्तर खात्रीशीर माहीत असते, तेव्हा मात्र ती अतिशय उत्साहाने आणि खूप छान उत्तरे देण्याचा प्रयत्न करते.',
            'आपल्या आजूबाजूच्या घडामोडींची आणि सामान्य गोष्टींची जाण तिला आहे. परंतु, आपले विचार स्वतःहून स्पष्टपणे आणि योग्य शब्दांत व्यक्त करण्यासाठी ती थोडा संकोच करते.',
        ],
        'awareness_parvat' => [
            'शिकवलेल्या गोष्टी तिला बहुतांश वेळा समजतात, मात्र त्या ठामपणे सांगण्यासाठी तिला शिक्षकांच्या आधाराची गरज भासते. उत्तरांमध्ये थोडीफार सुधारणा केल्यास ती खूप चांगली प्रगती करेल.',
            'पायाभूत बाबी समजण्यात तिला बऱ्यापैकी गती आहे, पण अजूनही वाचन आणि लेखनात तिला सरावाची गरज आहे. सरावाने ती नक्कीच अधिक चांगल्या प्रकारे स्वतःला व्यक्त करू शकेल.',
            'रोजच्या अभ्यासाव्यतिरिक्त ती इतर अवांतर गोष्टींतही चांगला रस घेते. प्रश्न विचारल्यास ती शांतपणे आणि बऱ्यापैकी बरोबर उत्तरे देते, ज्यात अजून प्रगल्भता येणे अपेक्षित आहे.',
            'नवीन घटक शिकण्याची तिची तयारी असते, परंतु सुरुवातीला ती थोडासा गोंधळून जाते. वारंवार उजळणी दिल्यास ती दिलेला सर्व अभ्यास अत्यंत व्यवस्थित आणि अचूकपणे करू शकतो.',
            'शिक्षकांनी सांगितलेली कामे ती अतिशय प्रामाणिकपणे पूर्ण करते आणि नियमांचे योग्य पालन करते. स्वतःहून फार धडपड करत नसला तरी दिलेला अभ्यास वेळेवर करून दाखवतो.',
        ],
        'awareness_pravah' => [
            'प्राथमिक संकल्पना समजून घेण्यास ती अजूनही बराच वेळ घेते. स्वतःचे विचार स्पष्टपणे आणि ठामपणे मांडण्यासाठी तिला सतत शिक्षकांनी प्रेमाने मार्गदर्शन करणे खूप आवश्यक आहे.',
            'शिकवलेल्या बाबी लगेच लक्षात राहण्यासाठी तिला वारंवार शिक्षकांच्या मदतीची आणि वैयक्तिक लक्ष देण्याची नितांत गरज भासते. ती अनेकदा स्वतःहून प्रश्न विचारताना कचरतो.',
            'प्रश्नांची उत्तरे देताना ती खूपदा गडबडतो किंवा चुकीची उत्तरे देते. तिला अधिक प्रोत्साहन देऊन आणि गोष्टी सोप्या करून सांगितल्यास ती योग्य दिशेने प्रगती करू शकतो.',
            'नवीन संकल्पना समजून घेण्यासाठी ती धडपड नक्कीच करते, पण तिला अनेकदा सहकाऱ्यांच्या मदतीची खूप गरज लागते. तिचे लक्ष खेळातून अभ्यासाकडे पूर्णपणे वळवण्यासाठी जास्तीचे प्रयत्न हवेत.',
            'विषयाची केवळ वरवरची ओळख झाली असून तिची अधिक सखोल उजळणी होणे अत्यंत आवश्यक आहे. स्वतःहून पुढाकार घेण्याची सवय तिला लावण्यासाठी सतत प्रोत्साहन द्यावे लागेल.',
        ],
        'sensitivity' => [
            'परिचित वातावरणात आणि मित्रमंडळींमध्ये ती खूप छान आणि मोकळेपणाने खेळते. मात्र, मोठ्या गटात किंवा अनोळखी लोकांशी बोलताना ती अजूनही बराच लाजतो आणि मागे राहते.',
            'खेळताना किंवा वर्गात कधी कधी त्याच्याकडून नियम मोडले जातात. पण तिला तिची चूक प्रेमाने दाखवून दिल्यावर ती ती लगेच मान्य करते आणि सुधारण्याचा प्रामाणिक प्रयत्न करते.',
            'आपल्या एक-दोन जवळच्या मित्रांसोबतच जास्त वेळ घालवणे आणि डबा खाणे ती नेहमी पसंत करते. सगळ्या वर्गासोबत एकरूप होण्यास आणि नवीन मित्र बनवण्यास तिला थोडा वेळ लागतो.',
            'स्वतःच्या भावना व्यक्त करताना तिला अनेकदा थोडी अडचण येते. एखादी गोष्ट हवी असल्यास किंवा त्रास होत असल्यास ती स्वतःहून फारसे स्पष्टपणे काहीच बोलत नाही.',
            'ती खोड्या काढून दुसऱ्यांना सहसा मुद्दाम काही त्रास देत नाही. बहुतांश वेळी ती अत्यंत शांत राहून आपल्याच विश्वासात आणि आपल्या आवडत्या गोष्टींमध्ये शांतपणे मग्न राहते.',
        ],
        'sensitivity_parvat' => [
            'सर्वांशी चांगले वागते आणि शाळेत सहसा कोणाशीही कोणतेही मोठे भांडण करत नाही. नियम आणि शिस्त पाळण्याचा तिचा प्रयत्न नेहमीच अतिशय चांगला आणि प्रामाणिक असते.',
            'बहुतांश वेळा ती शांत आणि समजूतदारपणे वागते आणि शिक्षकांच्या आज्ञेचे व्यवस्थित पालन करते. परंतु अनोळखी व्यक्तींसमोर ती स्वतःला व्यक्त करताना थोडाफार संकोचतो.',
            'इतरांच्या भावना तिला समजतात आणि ती मित्रांना सहसा कधीच दुखावत नाही. दैनंदिन व्यवहारात ती दिलेल्या सूचनांचे पालन करून सामाजिक नियमांशी जुळवून घेण्याचा चांगला प्रयत्न करते.',
            'मित्रांसोबत खेळताना ती सहकार्याची भावना नक्कीच दाखवतो. वागण्यात थोडा शांतपणा आणि लाजाळूपणा आहे, पण गरजेच्या वेळी ती मित्रांना आवर्जून मदत करते.',
            'वर्गातील शिस्त पाळतो आणि आपल्या कामाशी नेहमी प्रामाणिक राहते. मोठ्या समूहात बोलण्याची तिची फारशी हिंमत होत नसली तरी छोट्या गटात ती खूप खेळीमेळीने वावरतो.',
        ],
        'sensitivity_pravah' => [
            'नवीन परिस्थितीत जुळवून घेण्यास आणि लोकांशी मिसळण्यास तिला खूप जास्त वेळ लागतो. संवाद साधताना किंवा स्वतःला व्यक्त करताना तिची खूपच मोठी अडचण होते.',
            'इतरांच्या भावना समजून घेण्यात आणि त्यावर योग्य प्रतिक्रिया देण्यात ती अजूनही खूप संथ आहे. तिला मित्र बनवण्यासाठी आणि समंजसपणे वागण्यासाठी वारंवार मदतीची गरज भासते.',
            'खेळताना किंवा गटात काम करताना अनेकदा तिचे मित्रांसोबत छोटेमोठे वाद होतात. नियम पाळण्याची सवय तिला अद्याप पूर्णपणे लागलेली नाही, त्यासाठी सतत समज द्यावी लागते.',
            'लाजाळू स्वभावामुळे ती स्वतःहून नवीन मित्रांशी अजिबात ओळख करून घेत नाही. बदलत्या परिस्थितीला तोंड देण्यासाठी तिला चांगलाच आत्मविश्वास मिळवून द्यावा लागेल.',
            'वातावरणाशी एकरूप होताना ती अनेकदा भीती, संकोच किंवा अस्वस्थता दाखवतो. ती प्राथमिक संवादाची सुरुवात करण्यासाठी सर्वस्वी समोरच्या व्यक्तीवर किंवा शिक्षकांवर अवलंबून राहते.',
        ],
        'creativity' => [
            'साध्या आणि सोप्या कृती ती खूप चांगल्या प्रकारे स्वतःच्या स्वतः पूर्ण करते. मात्र, एखादी थोडी कठीण किंवा नवीन कल्पक कृती करताना तिला अनेकदा शिक्षकांच्या मदतीची गरज लागते.',
            'दिलेले चित्र रंगवताना अनेकदा रंगांची चुकीची निवड होते किंवा रंग बाहेर जातात. तरीही प्रत्येक गोष्ट जास्तीत जास्त चांगल्या प्रकारे पूर्ण करण्याचा तिचा प्रयत्न मात्र नक्कीच प्रामाणिक असते.',
            'स्वतःकडील साहित्याचा आणि कागदाचा वापर करून नेहमी काहीतरी बनवण्याचा तिचा चांगला प्रयत्न करते. पण तिच्या या रचना बऱ्याचदा खूप साध्या आणि प्राथमिक स्वरूपाच्या असतात.',
            'सर्वांसमोर उभे राहून गोष्ट किंवा गाणे म्हणायला सांगितल्यास ती सुरुवातीला थोडा मागे हटतो. पण गटात सर्वांसोबत असताना ती अतिशय उत्तम प्रकारे आणि जोरात गाणी म्हणते.',
            'तिच्या डोक्यात कल्पना नक्कीच खूप असतात पण त्या प्रत्यक्षात उतरवण्यासाठी त्याच्याकडे कौशल्याची थोडी कमी आहे. तिला यासाठी भरपूर सरावाची आणि शिक्षकांच्या सततच्या मदतीची सक्त गरज असते.',
        ],
        'creativity_parvat' => [
            'दिलेला नमुना किंवा चित्र बघून ती अत्यंत सुबकपणे आणि हुबेहूब त्याचप्रमाणे कृती पूर्ण करण्याचा चांगला प्रयत्न करते. तिचे काम बहुतांश वेळा खूप नीटनेटक्या स्वरूपाचे असते.',
            'रंगकाम आणि हस्तकलेत तिला बऱ्यापैकी आवड आहे असून ती दिलेले काम वेळेत संपवतो. स्वतःची थोडी बहुत कल्पकता त्यात जोडण्याचा तिचा प्रयत्न निश्चितच चांगला आणि कौतुकास्पद असते.',
            'साध्या आणि सोप्या कृती ती खूप योग्य प्रकारे पार पडतो. कागदकाम आणि साध्या चित्रकलेत तिचा हात चांगला बसला आहे, पण तिला अजूनही क्लिष्ट कामे करण्यासाठी मदतीची गरज लागते.',
            'शिक्षकांनी दिलेल्या सूचनांनुसार ती कलेच्या तासाला व्यवस्थित प्रतिसाद देते. स्वतःहून जास्त काही वेगळे बनवण्याची धडपड ती करत नसला, तरी ती सांगितलेले काम उत्तम दर्जाचे करते.',
            'मनापासून आणि भरपूर आवडीने ती कलेचे काम करते, पण स्वतःच्या कल्पना विस्तारासाठी तिला थोड्या अधिक मार्गदर्शनाची आणि प्रोत्साहनाची नक्कीच गरज भासते.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा ती प्रयत्न करते, त्यात सुबकतेचा आणि बारीकसारीक कलाकुसरीचा खूपच अभाव दिसतो. हस्तकलेच्या कामासाठी ती मदतीवर अवलंबून राहते.',
            'रंगकाम करताना रंग चित्राच्या नेहमीच बाहेर जातात आणि साहित्याचा वापर करताना तिला अडचण येते. चित्रकलेच्या तासाला नवीन काही रचना करण्यात ती सहसा रस दाखवत नाही.',
            'सूक्ष्म स्नायूंचा आणि बोटांचा समन्वय अजूनही कमी असल्याने तिला कागद कापणे किंवा पेन्सिलने अचूक आकार काढणे कठीण जाते. या कृती ती पूर्ण करण्यासाठी स्वतःहून फारसा धडपडत नाही.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये ती स्वतःला फारसे रमवू शकत नाही. एखादे साधे चित्र काढायला दिले तरी ती निरुत्साह दाखवतो आणि काम अपूर्ण सोडण्याची तिची सवय दिसून येते.',
            'कोणतीही नवीन कृती किंवा कला निर्माण करण्याची आवड त्याच्यात अजून अजिबात रुजलेली नाही. तिच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व सोप्या पद्धतीने शिकवावे लागते.',
        ],
    ],
    'L' => [
        'name' => 'प्रगती आवश्यक (Low)',
        'awareness' => [
            'काही अत्यंत प्राथमिक आणि पायाभूत गोष्टी समजण्यासाठी तिला इतरांपेक्षा थोडा अधिक वेळ लागतो. शिक्षकांना तिला या गोष्टी सतत वारंवार आणि खूप सोप्या भाषेत सांगाव्या लागतात, तेव्हाच तिला त्या थोडेफार समजतात.',
            'अभ्यासात तिचे लक्ष खूप लवकर विचलित होते आणि ती एका जागी स्थिर बसू शकत नाही. तिच्या मनात अभ्यासाविषयी रस आणि आवड निर्माण करण्यासाठी शिक्षकांना खूप वेगळे आणि नाविन्यपूर्ण प्रयोग रोज करावे लागतात.',
            'शिक्षकांनी दिलेल्या साध्या आणि सोप्या सूचनांचे योग्य अर्थ लावण्यास तिला बऱ्याचदा मोठी अडचण येते. कोणतेही काम किंवा अभ्यास स्वतःहून पुढाकार घेऊन करण्याची तिची वृत्ती अद्याप फारशी विकसित झालेली नाही.',
            'कोणत्याही नवीन गोष्टी किंवा संकल्पना शिकण्याबाबत त्याच्यामध्ये अनेकदा पूर्णपणे उदासिनता आणि निरुत्साह दिसून येते. तिला कशातच फारसा रस नसल्याचे तिच्या रोजच्या वागण्यातून वारंवार स्पष्टपणे जाणवते.',
            'तिच्या पायाभूत साक्षरता आणि प्राथमिक गणिती संकल्पना अजूनही खूप कच्च्या आणि कमकुवत आहेत. यावर मात करण्यासाठी तिला खूपच अधिक विशेष प्रयत्नांची आणि वैयक्तिक मार्गदर्शनाची सक्त गरज आहे.',
        ],
        'awareness_parvat' => [
            'शिक्षकांनी सांगितलेली कामे ती बहुतांश वेळा पूर्ण करण्याचा प्रयत्न करते, पण तिला अनेकदा पुन्हा पुन्हा सूचना देण्याची आणि सतत मार्गदर्शनाची खूप गरज भासते. उत्तरांमध्ये स्पष्टतेचा स्पष्ट अभाव जाणवतो.',
            'पायाभूत संकल्पना तिला थोड्याफार समजतात, पण ती त्या ठामपणे सांगताना नेहमीच खूप वेळ घेते किंवा गोंधळून जाते. भरपूर सराव आणि प्रेमाने समजावून सांगितल्यास तिच्या उत्तरात सुधारणा होऊ शकते.',
            'शिकवलेल्या बाबी लवकर लक्षात राहण्यासाठी तिला शिक्षकांच्या मदतीची आणि उजळणीची जास्त गरज लागते. रोजच्या सरावाने ती स्वतःला व्यक्त करण्यासाठी नक्कीच थोडे जास्त मोकळेपणे पुढे येऊ शकेल.',
            'नवीन घटक शिकताना ती थोडा बिचकत असला, तरी वारंवार सराव दिल्यास ती दिलेला अभ्यास पूर्ण करू शकतो. त्याच्याकडून योग्य आणि अचूक अभ्यास करून घेण्यासाठी सतत मागे लागून राहावे लागते.',
            'सर्वसाधारण गोष्टींची जाण तिला आहे, पण आपले विचार व्यवस्थित शब्दांत मांडण्यासाठी तिला अजूनही खूप संकोच वाटतो. या संकोची स्वभावामुळे ती अनेकदा स्वतःहून प्रश्नांची उत्तरे देणे जाणीवपूर्वक टाळतो.',
        ],
        'awareness_pravah' => [
            'कोणतीही साधी गोष्ट समजून घेण्यास तिला इतरांच्या मानाने खूप जास्त वेळ लागतो. आपले विचार स्पष्टपणे मांडण्यासाठी तिला सतत शिक्षकांनी आधार देणे आणि प्रोत्साहन देणे अत्यंत आवश्यक आहे.',
            'वर्गात शिकवलेल्या गोष्टी तिच्या फार काळ लक्षात राहत नाहीत आणि ती लवकर विसरून जाते. तिचे लक्ष अभ्यासात टिकवून ठेवण्यासाठी आणि रुची वाढवण्यासाठी खूप वेगळे आणि विशेष प्रयत्न करावे लागतात.',
            'प्रश्नांची उत्तरे देताना ती नेहमीच खूप गडबडतो किंवा चुकीची उत्तरे देते. तिला प्रत्येक गोष्ट अगदी शून्य स्तरापासून व सोप्या पद्धतीने परत-परत समजावून सांगण्याची मोठी गरज भासते.',
            'नवीन संकल्पना समजून घेण्यासाठी ती स्वतःहून फारसा अजिबात धडपडत नाही. तिचे लक्ष अभ्यासाकडे वळवण्यासाठी आणि ती अभ्यास पूर्ण करून घेण्यासाठी तिला सतत सहकाऱ्यांच्या किंवा शिक्षकांच्या मदतीची लागते.',
            'पुस्तकातील विषयाची तिला केवळ वरवरची आणि कमी ओळख झाली असून, तिची खूप सखोल आणि पुन्हा पुन्हा उजळणी होणे आवश्यक आहे. तिला स्वतःहून अभ्यासासाठी पुढाकार घेण्याची सवय अजूनही लागलेली नाही.',
        ],
        'sensitivity' => [
            'वर्गात किंवा गटात काम करताना अनेकदा ती इतर मुलांपासून लांब एकटाच गप्प बसणे पसंत करते. इतर विद्यार्थ्यांशी किंवा शिक्षकांशी तिचा संवाद खूप कमी आणि मर्यादित आहे.',
            'इतरांच्या भावना किंवा शाळेच्या रोजच्या नियमांबद्दल त्याच्यात फारशी कोणतीही समज नसल्याचे वारंवार तिच्या वागण्यातून दिसून येते. त्यामुळे ती अनेकदा नकळतपणे नियमांचे उल्लंघन करते.',
            'वागण्यात थोडा बालिशपणा असल्याने ती लहान-सहान आणि किरकोळ गोष्टींवरून खूप लवकर रडतो किंवा विनाकारण खूप चिडचिड करते. तिला समजावणे अनेकदा खूप मोठे आणि कठीण काम होऊन बसते.',
            'इतर मुलांसोबत खेळताना ती अनेकदा खेळाचे नियम स्वतःच्या मनाने मोडतो किंवा कंटाळा आला की मध्येच ती खेळ सोडून निघून जाते, ज्यामुळे इतरांना खूप मोठा त्रास होतो.',
            'नवीन शिक्षक, वर्गातील नवीन मुले किंवा शाळेत आलेल्या अनोळखी लोकांसमोर ती खूप जास्त घाबरल्यासारखा आणि अस्वस्थ वावरतो. तिच्या मनात अजूनही या गोष्टींबद्दल खूप संकोच आणि अनामिक भीती आहे.',
        ],
        'sensitivity_parvat' => [
            'परिचित वातावरणात ती छान खेळते, मात्र मोठ्या गटात किंवा अनोळखी लोकांशी बोलताना ती अजूनही पूर्णपणे लाजतो. मित्र बनवण्यास तिला खूप वेळ लागतो आणि ती मोजक्या मुलांसोबतच राहते.',
            'खेळताना अनेकदा नियम त्याच्याकडून नकळत मोडले जातात, पण समजून सांगितल्यास ती लगेच ऐकतो. आपल्या एक-दोन जवळच्या मित्रांसोबतच ती डबा खाणे आणि जास्त वेळ घालवणे पसंत करते.',
            'स्वतःच्या भावना व्यक्त करताना तिला खूप वेळेस मोठी अडचण येते. स्वतःला त्रास होत असल्यास किंवा काही हवे असल्यास ती स्वतःहून पुढे येऊन कधीही स्पष्टपणे बोलत नाही, तिला सारखे विचारावे लागते.',
            'ती खोड्या काढून कुणाला त्रास देत नाही, बहुतांश वेळी ती अत्यंत शांत राहते. मात्र, सर्व वर्गासोबत एकरूप होण्यास तिला भरपूर वेळ लागतो आणि ती खूपदा आपल्याच विश्वासात आणि विचारात मग्न राहते.',
            'शाळेतील शिस्त पाळतो, पण मोठ्या समूहात बोलण्याची तिची हिंमत होत नाही. सहकार्याची भावना असली तरी लाजाळू स्वभावामुळे ती स्वतःहून कोणाला मदत करायला पुढे येत नाही किंवा मदत मागतही नाही.',
        ],
        'sensitivity_pravah' => [
            'नवीन वातावरणात जुळवून घेण्यास तिला खूप वेळ लागतो आणि संवाद साधताना प्रचंड अडचण येते. इतरांच्या भावना समजून घेण्यात ती खूप संथ आहे आणि योग्य प्रतिक्रिया देण्यास तिला अजिबात जमत नाही.',
            'खेळताना वारंवार मित्रांसोबत तिचे वाद होतात आणि नियम पाळण्याची सवय तिला अजूनही अजिबात लागलेली नाही. त्यासाठी शिक्षकांना सतत त्याच्यावर लक्ष ठेवून तिला योग्य ती समज द्यावी लागते.',
            'लाजाळू वागणुकीमुळे ती नवीन मित्रांशी अजिबात ओळख करून घेत नाही, आणि एकटाच राहणे कायम पसंत करते. बदलत्या परिस्थितीला तोंड देण्याचा आत्मविश्वास त्याच्यात अजूनही पूर्णपणे विकसित व्हायचा आहे.',
            'वातावरणाशी एकरूप होताना ती अनेकदा खूप संकोच, भीती किंवा अस्वस्थता दाखवतो. संवादाची सुरुवात करण्यासाठी ती नेहमीच दुसऱ्यांवर अवलंबून असते आणि स्वतःहून कधीच कोणाशी बोलत नाही.',
            'शाळेत आल्यावर अनेकदा ती खूप रडतो किंवा शांत कोपऱ्यात जाऊन बसते. समंजसपणे वागण्यासाठी आणि इतर मुलांसोबत जोडण्यासाठी तिला रोज शिक्षकांच्या प्रेमाने वेळ देऊन समजावण्याची गरज असते.',
        ],
        'creativity' => [
            'कोणतेही दिलेले छोटेसे काम सुरू करण्यासाठी ती पूर्णपणे आणि फक्त शिक्षकांच्या मदतीवर किंवा सूचनेवरच अवलंबून राहते. ती स्वतःहून अजिबात कोणतेही काम सुरू करू शकत नाही.',
            'रंगकाम किंवा कोणत्याही हस्तकलेत ती अजिबात काडीचाही रस दाखवत नाही. तिचे हे काम केवळ कागद फाडणे, चुरगळणे किंवा कागदावर अर्थहीन रेष ओढण्यापुरतेच कायम मर्यादित राहिलेले आहे.',
            'कल्पनाशक्तीला किंवा विचारशक्तीला चालना देणाऱ्या साध्या कृती करताना ती नेहमी पूर्णपणे गप्प बसते आणि कोणताही प्रतिसाद देत नाही. तिला या गोष्टी समजण्यात खूपच जास्त वेळ लागतो.',
            'शारीरिक हालचालींचे सोपे खेळ सोडल्यास, तिला इतर कोणत्याही बौद्धिक कृतीत किंवा खेळात खेळताना खूप लवकर कंटाळा येते. यामुळे ती अशा खेळात सहसा कधीच सहभागी होत नाही.',
            'कागदाची नाव किंवा विमान अशी कोणतीही अत्यंत साधी रचना करण्यासाठी तिला शिक्षकांना पुन्हा पुन्हा अनेकदा प्रात्यक्षिक करून दाखवावे लागते, तरीही तिला ते अचूक बनवता येत नाही.',
        ],
        'creativity_parvat' => [
            'साध्या आणि सोप्या कृती ती बऱ्यापैकी पूर्ण करते, पण कठीण किंवा नवीन कृती करताना तिला मदतीची गरज लागते. रंगांची थोडी गल्लत होते पण काम पूर्ण करण्याचा तिचा नेहमी प्रयत्न असते.',
            'साहित्याचा वापर करून काही तरी बनवण्याचा ती प्रयत्न करते, पण या रचना अतिशय साध्या असतात. सर्वासमोर गाणे म्हणायला सांगितल्यास ती मागे हटतो, पण गटात सर्वांसोबत असताना छान गातो.',
            'दिलेला नमुना किंवा चित्र बघून त्याच्याच सारखे साधे काम करण्याचा तिचा प्रयत्न असते. तिचे काम अनेकदा योग्य असले तरी তাতে कल्पकतेचा खूप मोठा अभाव असते आणि सफाई कमी असते.',
            'कागदकाम आणि चित्रकलेत ती फक्त सोपे काम पूर्ण करू शकतो, क्लिष्ट कामे तिला अजिबात जमत नाहीत. तिला स्वतःच्या कल्पना विस्तारासाठी अधिक मार्गदर्शनाची आणि प्रोत्साहनाची कायम गरज भासते.',
            'शिक्षकांनी सांगितलेल्या सूचनांनुसार ती साधे काम पूर्ण करू शकतो. पण स्वतःहून जास्त काही वेगळे आणि नवीन बनवण्याची धडपड ती मुळीच करत नाही, ती सांगितलेले काम फक्त कसेबसे संपवतो.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची केवळ साधी नक्कल करण्याचा ती प्रयत्न करते, आणि त्यात सुबकतेचा खूपच जास्त अभाव दिसतो. हस्तकलेच्या कामासाठी ती पूर्णपणे दुसऱ्यांच्या किंवा शिक्षकांच्या मदतीवरच अवलंबून राहते.',
            'रंगकाम करताना नेहमीच रंग चित्राच्या पूर्णपणे बाहेर जातात आणि साहित्याचा नीट वापर करताना तिला मोठी अडचण येते. चित्रकलेच्या तासाला नवीन रचना करण्यात ती अजिबात रस दाखवत नाही.',
            'सूक्ष्म स्नायूंचा समन्वय कमी असल्याने तिला कागद कापणे किंवा अचूक आकार काढणे खूपच कठीण जाते. या कृती पूर्ण करण्यासाठी ती काहीही प्रयत्न करत नाही आणि काम लगेच सोडून देते.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये ती स्वतःला अजिबात रमवू शकत नाही. साधे चित्र काढायला दिले तरी ती पूर्ण निरुत्साह दाखवतो आणि काम अर्धवट टाकून किंवा अपूर्ण सोडण्याची तिची सवय दिसून येते.',
            'कोणतीही नवीन कला निर्माण करण्याची आवड त्याच्यात अजून अजिबात रुजलेली नाही. तिच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व खूप साध्या पद्धतीने तिला पुन्हा पुन्हा शिकवावे लागते.',
        ],
    ],
    'VL' => [
        'name' => 'विशेष मदत आवश्यक (Very Low)',
        'awareness' => [
            'ज्ञान आणि विविध संकल्पना ग्रहण करण्याची तिची क्षमता अद्याप अत्यंत कमी स्तरावर आहे. तिला अभ्यासाच्या प्रवाहात आणण्यासाठी दैनंदिन पातळीवर खूप विशेष आणि सातत्यपूर्ण मार्गदर्शनाची अत्यंत निकड आहे.',
            'शिक्षकांनी सांगितलेल्या गोष्टी ती वारंवार सांगूनही फार काळ लक्षात ठेवत नाही आणि लवकर विसरतो. वर्गात बसलेले असताना तिचे लक्ष पूर्णपणे दुसरीकडेच असते आणि अभ्यासात ती अजिबात रस घेत नाही.',
            'अभ्यासाच्या साहित्याचा आणि साधनांचा योग्य प्रकारे वापर करण्यास त्याच्यामध्ये खूपच मोठी असमर्थता दिसून येते. कोणतेही शैक्षणिक साहित्य हाताळताना ती अनेकदा खूप गोंधळलेला आणि दिशाहीन वाटतो.',
            'बौद्धिक किंवा शैक्षणिक प्रकारच्या कोणत्याही अध्ययनामध्ये ती स्वतःहून अजिबात रुची किंवा उत्साह दाखवत नाही. तिला अभ्यासाला बसवण्यासाठी शिक्षकांना आणि पालकांना रोज खूप मोठी कसरत करावी लागते.',
            'तिच्या पायाभूत आणि प्राथमिक संकल्पना पूर्णपणे कच्च्या असून त्या अगदी नव्याने आणि शून्यातून शिकवाव्या लागतात. तिला या सर्व गोष्टी अत्यंत सोप्या भाषेत वारंवार आणि पुन्हा-पुन्हा सांगण्याची गरज आहे.',
        ],
        'awareness_parvat' => [
            'शिक्षकांनी दिलेल्या अगदी सोप्या सूचनांचे पालन करण्याचा ती काही प्रमाणात प्रयत्न करते, पण तिला सातत्याने मदतीची गरज लागते. तिच्या बौद्धिक आणि आकलन क्षमतेत हळूहळू आणि संथ गतीने सुधारणा होण्याची थोडी शक्यता आहे.',
            'पायाभूत बाबींची थोडीफार आणि पुसटशी ओळख तिला झाली आहे, पण ती त्याबद्दल काहीही सांगताना पूर्णपणे गोंधळून जाते. भरपूर सराव आणि प्रेमाने हाताळल्यास तिच्या ज्ञानात थोडीफार वाढ होऊ शकते.',
            'शिक्षकांनी वारंवार लक्ष दिल्यावर ती एखादी साधी गोष्ट लक्षात ठेवण्याचा प्रयत्न करते, पण ती लवकरच विसरूनही जाते. रोजच्या नियमित सरावाने ती पुढील काळात नक्कीच थोडी अधिक प्रगती दाखवू शकेल.',
            'नवीन कोणतेही घटक शिकताना ती खूप जास्त बिचकत आणि घाबरत असला, तरी वारंवार सराव दिल्यास ती दिलेला अभ्यास पूर्ण करू पाहते. अभ्यासाची सवय लावण्यासाठी त्याच्याकडून अगदी सोपी कामे करून घ्यावी लागतात.',
            'सर्वसाधारण रोजच्या गोष्टींची तिला थोडी-बहुत जाण आहे, पण आपले विचार शब्दांत मांडणे तिला जवळजवळ अशक्य वाटते. या स्वभावामुळे ती अनेकदा स्वतःहून कोणतेही उत्तर देणे किंवा बोलणे टाळतो.',
        ],
        'awareness_pravah' => [
            'कोणतीही अगदी साधी गोष्ट समजून घेताना तिला इतरांपेक्षा असामान्य आणि खूप जास्त वेळ लागतो. आपले प्राथमिक विचार मांडण्यासाठी तिला सतत शिक्षकांनी आधार आणि शब्द पुरवणे अत्यंत आवश्यक आहे.',
            'शिकवलेल्या गोष्टी तिच्या अजिबात लक्षात राहत नाहीत आणि ती अभ्यासातील बारकावे पूर्णपणे विसरून जाते. तिचे लक्ष केवळ काही मिनिटेच टिकते, त्यामुळे तिला शिकवण्यासाठी खूप विशेष आणि कमी वेळाचे प्रयोग करावे लागतात.',
            'साध्या प्रश्नांची उत्तरे देतानाही ती पूर्णपणे गोंधळतो किंवा फक्त शांत राहून बघत राहते. तिला प्रत्येक गोष्ट अगदी शून्य स्तरापासून व खूप सोप्या पद्धतीने परत-परत समजावून सांगण्याची मोठी गरज भासते.',
            'कोणत्याही नवीन शैक्षणिक संकल्पना समजून घेण्यासाठी ती स्वतःहून अजिबात पुढाकार घेत नाही किंवा तशी धडपड करत नाही. तिला अभ्यासाकडे वळवण्यासाठी सतत शिक्षकांच्या वैयक्तिक मदतीची आणि लक्ष देण्याची गरज लागते.',
            'पुस्तकातील कोणत्याही विषयाची तिला केवळ नाममात्र ओळख असून, तिची संपूर्ण व सखोल उजळणी होणे आवश्यक आहे. तिला स्वतःहून अभ्यासासाठी पुढाकार घेण्याची सवय अजूनही अजिबात लागलेली नाही आणि ती लावणे कठीण आहे.',
        ],
        'sensitivity' => [
            'तिची संवाद साधण्याची आणि संभाषण क्षमता खूपच कमी आणि प्राथमिक स्तरावर आहे. अनोळखी लोकांसमोर किंवा नवीन शिक्षकांसमोर ती अनेकदा पूर्णपणे गप्प आणि स्तब्ध राहते.',
            'इतर मुलांच्या गटात मिसळणे ती जाणीवपूर्वक टाळतो आणि नेहमी एकटा बसून स्वतःच्या विश्वातच मग्न राहते. तिला इतर मुलांसोबत खेळायला किंवा डबा खायला अजिबात आवडत नाही.',
            'शाळेचे दैनंदिन नियम पाळण्यात आणि शाळेची रोजची दिनचर्या समजून घेण्यात तिला प्रचंड अडथळे आणि अडचणी येतात. ती वारंवार नियमांचे उल्लंघन करून वर्गात उगीचच गोंधळ घालतो.',
            'इतरांच्या भावनांची तिला कोणतीही समज किंवा जाणीव नसल्याचे तिच्या वागणुकीवरून स्पष्टपणे जाणवते. ती अनेकदा खूपच हट्टीपणा करते आणि स्वतःला हवे तसे वागण्याचा दुराग्रह धरतो.',
            'शाळेतील शिस्त, नियम आणि पद्धत आत्मसात करण्यास तिला अजूनही अजिबात यश आलेले नाही. तिला समजावून सांगणे हे शिक्षकांसाठी अनेकदा एक मोठे आणि थकवणारे आव्हान ठरते.',
        ],
        'sensitivity_parvat' => [
            'परिचित वातावरणात ती थोडा वेळ छान खेळते, मात्र मोठ्या गटात किंवा अनोळखी लोकांशी बोलताना ती स्वतःला लगेच लपवतो. मित्र बनवण्यास तिला खूप वेळ लागतो आणि ती केवळ एकाच मित्रासोबत नेहमी राहते.',
            'खेळताना अनेकदा साधे नियम त्याच्याकडून वारंवार मोडले जातात, पण कडक समजून सांगितल्यास ती काही काळ ऐकतो. डबा खातानाही ती एकटाच खाणे पसंत करते आणि इतरांना स्वतःचे काहीच देत नाही.',
            'स्वतःच्या अगदी प्राथमिक भावना व्यक्त करताना तिला खूप मोठी अडचण येते. स्वतःला त्रास होत असल्यास किंवा पाणी हवे असल्यास ती स्वतःहून क्वचितच बोलते, तिला या गोष्टींसाठी सतत विचारावे लागते.',
            'ती अनेकदा खोड्या काढून कुणाला त्रास देते, पण विचारल्यावर मात्र आपण काहीच केले नाही अशी अत्यंत शांत राहते. सर्व वर्गासोबत एकरूप होण्यास तिला भरपूर वेळ लागतो आणि ती अभ्यासाव्यतिरिक्त इतर गोष्टीत मग्न राहते.',
            'शाळेतील शिस्त पाळण्यासाठी तिला सतत सूचना द्याव्या लागतात, मोठ्या समूहात ती कधीच उभा राहायला तयार नसतो. सहकार्याची भावना त्याच्यात अत्यंत कमी असून ती स्वतःहून कोणालाही कधी मदत करत नाही.',
        ],
        'sensitivity_pravah' => [
            'नवीन वातावरणात जुळवून घेण्यास तिला अतोनात वेळ लागतो आणि लहानसा संवाद साधतानाही प्रचंड अडचण आणि मानसिक ताण येते. इतरांच्या भावना ती अजिबात समजत नाही आणि तिच्या प्रतिक्रिया अत्यंत चुकीच्या असू शकतात.',
            'खेळताना नेहमीच मित्रांसोबत तिचे गंभीर वाद आणि भांडणे होतात, नियम पाळण्याची सवय तिला अजिबात लागलेली नाही आणि ती तसा प्रयत्नच करत नाही. त्यासाठी शिक्षकांना त्याच्यावर प्रत्येक क्षणी लक्ष ठेवावे लागते.',
            'लाजाळू वागणुकीसोबतच त्याच्यात थोडा आक्रस्ताळेपणा असल्याने ती नवीन मित्रांशी ओळख करत नाही आणि सगळ्यांपासून अलिप्त राहते. परिस्थितीला तोंड देण्याचा आत्मविश्वास त्याच्यात अजूनही पूर्णपणे विकसित व्हायचा आहे.',
            'वातावरणाशी एकरूप होताना ती अनेकदा खूप संकोच, भीती, अस्वस्थता दाखवतो किंवा मोठ्याने रडतो. संवादाची सुरुवात करण्यासाठी ती दुसऱ्यांवर अवलंबून असते आणि अनेकदा कोणाशीच न बोलण्याचा हट्ट धरून बसते.',
            'शाळेत आल्यावर अनेकदा ती खूप रडून आईला परत बोलावण्याचा आग्रह धरतो, किंवा वर्गाबाहेर पळून जाण्याचा प्रयत्न करते. സമंजसपणे वागण्यासाठी आणि रुळावर आणण्यासाठी तिला रोज शिक्षकांच्या अत्यंत विशेष प्रयत्नांची गरज असते.',
        ],
        'creativity' => [
            'हातापायांच्या आणि बोटांच्या सूक्ष्म स्नायूंचा विकास अजूनही खूप कमी असल्याने तिला अतिशय साध्या कृती करतानाही खूप त्रास होतो. तिला सर्व कामात पूर्णपणे दुसऱ्यांवर अवलंबून राहावे लागते.',
            'कागद योग्य प्रकारे पकडणे, पेन्सिल व्यवस्थित धरणे किंवा सरळ रेष मारणे यासारख्या अत्यंत बारीक आणि प्राथमिक कामात तिला बरीच अडचण येते. तिचे काम अतिशय अस्वच्छ असते.',
            'तिची कल्पनाशक्ती खूपच मर्यादित आणि कमकुवत आहे. ती स्वतःहून कोणतीही नवीन कृती किंवा रचना करत नाही आणि शिक्षकांनी सांगितल्यावरही तिला काहीच सुचत नाही.',
            'शिक्षकांनी स्वतः तिच्या हाताला धरून काम करवून घेतल्याशिवाय ती कोणत्याही कृतीत किंवा खेळात अजिबात सहभाग घेत नाही. ती अनेकदा काम करण्यास स्पष्ट नकार देते.',
            'त्याच्यातील सर्जनशील आणि कलात्मक क्षमतांचा विकास खूपच प्रारंभिक स्तरावर थांबलेला आहे. त्यात सुधारणा करण्यासाठी तिला अगदी सुरुवातीपासून व जादा वेळे देऊन हस्तकला शिकवावी लागेल.',
        ],
        'creativity_parvat' => [
            'साध्या आणि भौतिक कृती ती कसेबसे पूर्ण करते, पण कोणतीही थोडी कठीण कृती करताना तिला पूर्णपणे मदतीची गरज लागते. रंगांची ओळख तिला अद्याप स्पष्ट नसल्याने काम नेहमी चुकीचे आणि अस्वच्छ असते.',
            'साहित्याचा नुसता वापर करून काही तरी वेडेवाकडे बनवण्याचा ती प्रयत्न करते, पण या रचना अतिशय अर्थहीन असतात. सर्वासमोर गाणे म्हणायला सांगितल्यास ती लगेच रडायला लागतो आणि काहीच बोलत नाही.',
            'दिलेला नमुना बघून त्याच्यासारखे काम करण्याचा तिचा प्रयत्न असते, पण सूक्ष्म स्नायूंचा विकास कमी असल्याने ते जमत नाही. तिचे काम नेहमी अर्धवट किंवा चुकीचे असते आणि তাতে कल्पकतेचा खूप मोठा अभाव असते.',
            'कागदकाम आणि चित्रकलेत ती फक्त कागद चुरगळणे असेच काम करू शकतो, क्लिष्ट कामे तिला अजिबात जमत नाहीत. तिला स्वतःच्या कल्पना विस्तारासाठी अत्यंत प्राथमिक आणि विशेष मार्गदर्शनाची गरज भासते.',
            'शिक्षकांनी दिलेल्या सूचना तिला पूर्णपणे समजत नाहीत आणि ती काम करताना दिशाहीन होतो. स्वतःहून काही वेगळे बनवण्याची धडपड ती मुळीच करत नाही, ती फक्त समोर दिलेले काम कसेतरी संपवण्याच्या घाईत असते.',
        ],
        'creativity_pravah' => [
            'दिलेल्या नमुन्याची नक्कल करणेही तिला अजिबात जमत नाही आणि त्यात सुबकतेचा १०० टक्के अभाव दिसतो. हस्तकलेच्या कोणत्याही कामासाठी ती पूर्णपणे आणि फक्त शिक्षकांच्या मदतीवरच अवलंबून राहते.',
            'रंगकाम करताना नेहमीच रंग चित्राच्या पूर्णपणे बाहेर जातात, कागद फाटतो आणि साहित्याचा नीट वापर करताना तिला मोठी अडचण येते. चित्रकलेच्या तासाला ती केवळ रेषे मारून वही खराब करण्यातच मग्न असते.',
            'सूक्ष्म स्नायूंचा समन्वय अतिशय कमी असल्याने तिला कागद कापणे किंवा पेन्सिलने आकार काढणे अशक्य जाते. या कृती पूर्ण करण्यासाठी ती काहीही सकारात्मक प्रयत्न करत नाही आणि काम लगेच सोडून रडू लागतो.',
            'सर्जनशील आणि कल्पकतेच्या कृतींमध्ये ती स्वतःला अजिबात रमवू शकत नाही आणि इतर मुलांनाही काम करू देत नाही. चित्र काढायला दिले तरी ती निरुत्साह दाखवतो आणि काम अर्धवट टाकून वर्गात पळण्याची तिची सवय दिसून येते.',
            'कोणतीही साधी कला निर्माण करण्याची क्षमता त्याच्यात अजून अजिबात रुजलेली नाही. तिच्या कलागुणांना वाव देण्यासाठी अगदी शून्य स्तरापासून व खूप साध्या पद्धतीने तिला हाताला धरून पुन्हा पुन्हा जास्तीचा वेळ देऊन शिकवावे लागते.',
        ],
    ],
];

