$hpc_activity_descriptions = [
    'boys' => [
        'VH' => [
            'term1' => [
                'पहिल्या सत्रात वर्गात घेतलेल्या जवळपास सर्वच कृतींत त्याने खूप उमेदीने आणि उत्साहाने भाग घेतला. गटचर्चा, प्रश्नमंजुषा आणि सादरीकरणात त्याचा सहभाग खूपच वाखणण्याजोगा आणि इतरांसाठी प्रेरक होता.',
