                'सुरुवातीपासूनच वर्गात खूप चलाख आणि एक्टिव्ह असलेला हा मुलगा प्रत्येक कामात नेहमी पुढे असायचा. कोणतेही नवीन आव्हान त्याने हसतमुखाने स्वीकारले आणि ते पूर्ण करण्यासाठी स्वतःची शंभर टक्के ताकद लावली.',
