            ],
            'term2' => [
                'दुसऱ्या सत्रात अभ्यासातील कठीण संकल्पना सुद्धा त्याने लीलया आणि अतिशय सोप्या पद्धतीने पार केल्या. शाळेचा वार्षिक प्रकल्प पूर्ण करण्यात आणि त्याचे सादरीकरण करण्यात {tycha} अत्यंत महत्त्वाचा आणि मोठा वाटा होता.',
                'हस्तकलेचे, ओरिगामीचे आणि विज्ञानाचे प्रयोग करताना त्याने फक्त स्वतःच नवीन गोष्टी शिकल्या नाहीत, तर वर्गातील इतर विद्यार्थ्यांनाही त्यांचे प्रयोग पूर्ण करण्यासाठी खूप छान आणि अत्यंत उपयुक्त मार्गदर्शन केले.',
                'शालेय क्रीडा स्पर्धांमध्ये, तसेच स्नेहसंमेलनाच्या सांस्कृतिक कार्यक्रमात त्याने अतिशय जोमाने आणि आत्मविश्वासाने भाग घेतला. स्वतःच्या उत्कृष्ट कामगिरीच्या जोरावर त्याने अनेक बक्षिसे आणि सर्वांची शाबासकी मिळवली.',
