                'आता तो वर्गात शिकत असताना शिक्षकांना थोडे फार प्रश्न स्वतःहून विचारायला लागला आहे. यातून ज्ञान मिळवण्याचा त्याचा आत्मविश्वास थोडा निश्चितच वाढलेला दिसून येतो.',
                'गणितातील बेरीज आणि वजाबाकी तो शिक्षकांच्या थोड्या मदतीने अचूक सोडवतो. हे सर्व स्वतःहून सोडवण्यासाठी त्याला अजून भरपूर सरावाची नक्कीच गरज भासते आहे.',
                'शाळेच्या स्नेहसंमेलन आणि सांस्कृतिक कार्यक्रमात त्याने समूहात अतिशय छान आणि सुंदर सादरीकरण केले. आता लोकांसमोर जाण्याची त्याची स्वतःची भीती थोडी कमी झाल्याचे स्पष्ट दिसते.',
                'मित्रांसोबतची त्याची सहकार्याची भावना वाढीस लागली असून, तो आता इतरांसोबत समजूतदारपणे मिळून कोणत्याही गटात सर्वांच्या सोबत काम करणे त्याला चांगले जमू लागले आहे.',
            ],
        ],
        'L' => [
            'term1' => [
