                'अनेक शैक्षणिक खेळांमधून त्याला शिकवण्याचा प्रयत्न झाला, पण एकाग्रता न टिकल्याने आउटपुट कमी आले.',
                'साध्या ध्वनी ऐकणे आणि अक्षरे गिरवणे यामध्ये त्याने खूप वेळ घेतला.',
