                'अक्षरांचे थोडेफार वाचन करू लागला आहे, पण गती खूपच कमी आहे.',
                'वैयक्तिक लक्ष दिल्यावर तो काम पूर्ण करण्याचा प्रयत्न करतो, पण स्वतःहून सुरुवात करत नाही.',
                'मोठ्या गटाच्या कृतींऐवजी दोन-तीन मुलांच्या गटात तो थोडे बरे काम करतो.',
                'वागणुकीत थोडी शांतता आली आहे, मात्र शैक्षणिक प्रगती अजूनही खूप बाकी आहे.',
            ],
        ],
        'VL' => [
            'term1' => [
