    'girls' => [
        'VH' => [
            'term1' => [
                'पहिल्या सत्रात वर्गात घेतलेल्या जवळपास सर्वच कृतींत तिने खूप उमेदीने आणि उत्साहाने भाग घेतला. गटचर्चा, प्रश्नमंजुषा आणि सादरीकरणात तिचा सहभाग खूपच वाखणण्याजोगा आणि इतरांसाठी प्रेरक होता.',
                'पावसाळी सहल आणि निसर्ग निरीक्षणाच्या तासाला तिने अतिशय बारकाईने आजूबाजूच्या परिसराचे निरीक्षण करून स्वतःचे अनोखे अनुभव वर्गात अत्यंत प्रभावीपणे शेअर केले. तिची निरीक्षण शक्ती खरोखरच अफाट आहे.',
                'शिक्षकांनी वर्गात दिलेल्या विज्ञानाच्या प्रयोगांमध्ये आणि मैदानी खेळांमध्ये {tyाने} खूप कल्पकतेने आणि हुशारीने सहभाग घेतला. प्रत्येक कृती मागे असणारे कारण समजून घेण्याची तिची वृत्ती प्रकर्षाने दिसून आली.',
                'सुरुवातीपासूनच वर्गात खूप चलाख आणि एक्टिव्ह असलेली हा मुलगी प्रत्येक कामात नेहमी पुढे असायचा. कोणतेही नवीन आव्हान तिने हसतमुखाने स्वीकारले आणि ते पूर्ण करण्यासाठी स्वतःची शंभर टक्के ताकद लावली.',
