            ],
            'term2' => [
                'दुसऱ्या सत्रात अभ्यासातील कठीण संकल्पना सुद्धा तिने लीलया आणि अतिशय सोप्या पद्धतीने पार केल्या. शाळेचा वार्षिक प्रकल्प पूर्ण करण्यात आणि तिचे सादरीकरण करण्यात {tycha} अत्यंत महत्त्वाचा आणि मोठा वाटा होता.',
                'हस्तकलेचे, ओरिगामीचे आणि विज्ञानाचे प्रयोग करताना तिने फक्त स्वतःच नवीन गोष्टी शिकल्या नाहीत, तर वर्गातील इतर विद्यार्थ्यांनाही त्यांचे प्रयोग पूर्ण करण्यासाठी खूप छान आणि अत्यंत उपयुक्त मार्गदर्शन केले.',
                'शालेय क्रीडा स्पर्धांमध्ये, तसेच स्नेहसंमेलनाच्या सांस्कृतिक कार्यक्रमात तिने अतिशय जोमाने आणि आत्मविश्वासाने भाग घेतला. स्वतःच्या उत्कृष्ट कामगिरीच्या जोरावर तिने अनेक बक्षिसे आणि सर्वांची शाबासकी मिळवली.',
                'शाळेत आयोजित केलेल्या विज्ञान आणि कला प्रदर्शनात तिने स्वतःच्या हाताने तयार केलेल्या वस्तू आणि मॉडेल्स अतिशय सुंदररीत्या मांडले. तिच्या या कलाकृतींचे सर्व शिक्षक आणि भेटीला आलेल्या पालकांनी भरभरून कौतुक केले.',
