$hpc_annual_feedback = [
    'boys' => [
        'VH' => [
            'ह्या विद्यार्थीची वर्षभरातील प्रगती खूपच समाधानकारक आणि डोळ्यांत भरणारी आहे. अभ्यासात आणि खेळात तो अतिशय हुशार असून प्रत्येक क्षेत्रात त्याने आपल्या अंगभूत गुणांची उत्तम चमक दाखवली आहे. पुढील शैक्षणिक वाटचालीसाठी खूप खूप शुभेच्छा!',
