            'शाळेतील सर्वच उपक्रमात अत्यंत उमेदीने आणि हिरिरीने भाग घेऊन काम करण्याची त्याची पद्धत खूप मस्त आणि आदर्शवत आहे. स्वतःबरोबरच वर्गातील इतर मुलांनाही अभ्यासात मदत करण्याच्या त्याच्या गुणांचे करावे तितके कौतुक थोडेच आहे.',
            'अतिशय गुणी, प्रामाणिक आणि हुशार असलेला हा विद्यार्थी खऱ्या अर्थाने वर्गाची शान आहे. त्याने वर्षभरात आपल्या क्षमतांचा संपूर्ण ताकदीने वापर करून अतिशय उत्तम प्रगती साध्य केली आहे. पुढील वर्गातही असाच प्रथम क्रमांकावर राहा!',
            'कोणत्याही वातावरणाशी झटपट एकरूप होणारा आणि नवनवीन गोष्टी शिकण्यासाठी सतत धडपडणारा हा एक उत्कृष्ट आणि सर्वगुणसंपन्न विद्यार्थी आहे. शिक्षकांची प्रत्येक सूचना तो तंतोतंत पळतो. त्याच्या सुयशपूर्ण भविष्यासाठी सदिच्छा!',
        ],
        'H' => [
            'ह्या विद्यार्थीची वर्षभरातील प्रगती खूपच उत्तम आणि समाधानकारक आहे. अभ्यासात आणि मैदानी खेळात तो अतिशय हुशार आहे. पुढील शैक्षणिक वाटचालीसाठी त्याला शाळेतर्फे खूप खूप शुभेच्छा!',
            'त्याची अंगभूत जिज्ञासू वृत्ती आणि अभ्यास करण्याची प्रचंड आवड बघून आम्हा सर्व शिक्षकांना खूप आनंद होतो. असाच चिकाटीने पुढे जात राहा, तू नक्कीच भविष्यात मोठे यश संपादन करशील!',
