/**
 * SCERT संच बँक (cce_sanch / cce_sanch2) मधील अधिकृत पातळी-वर्णने
 * $demo_rubric_descriptions मध्ये जोडली जातात, जेणेकरून HPC कार्डच्या
 * रुब्रिक ड्रॉपडाउनमध्ये शासनमान्य मजकूर उपलब्ध होतो.
 */
function hpc_merge_sanch_descriptors(array $base, ?int $std = null, string $gender = 'M'): array
{
    static $cache = [];
    $key = ($std ?? 0) . '|' . $gender;
    if (isset($cache[$key])) return $cache[$key];
    $table = (strtoupper($gender) === 'F' || $gender === 'मुलगी') ? 'cce_sanch2' : 'cce_sanch';
    try {
        $db = getDB();
        $sql = "SELECT kode, nirzar1, nirzar2, nirzar3, parvat1, parvat2, parvat3, akash1, akash2, akash3 FROM `$table`";
        if ($std) { $sql .= ' WHERE std = ' . (int) $std; }
        $rows = $db->query($sql)->fetchAll(PDO::FETCH_ASSOC);
    } catch (Throwable $e) {
        return $cache[$key] = $base;
    }
    $dims = ['awareness' => 1, 'sensitivity' => 2, 'creativity' => 3];
    foreach ($rows as $r) {
        $did = (int) $r['kode'];
        if ($did < 1 || $did > 6) continue;
        foreach ($dims as $dim => $n) {
            $map = [
                'pailu'  => (string) ($r['nirzar' . $n] ?? ''),
                'pravah' => (string) ($r['nirzar' . $n] ?? ''),
                'parvat' => (string) ($r['parvat' . $n] ?? ''),
                'akash'  => (string) ($r['akash' . $n] ?? ''),
            ];
            foreach ($map as $lvl => $txt) {
                $txt = trim($txt);
                if ($txt === '') continue;
                $cur = $base[$did][$dim][$lvl] ?? [];
                if (!is_array($cur)) $cur = $cur === '' ? [] : [$cur];
                if (!in_array($txt, $cur, true)) $cur[] = $txt;
                $base[$did][$dim][$lvl] = $cur;
            }
        }
    }
    return $cache[$key] = $base;
}
